{
  "name": "Sarf (صرف)",
  "description": "A high-performance personal expense tracking application with category management, PDF reporting, and secure data handling, designed with a sleek Arabic-first dark interface.",
  "requestFramePermissions": [
    "camera"
  ]
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export interface Category {
  id: string;
  name: string;
  color: string;
  order: number;
  isDefault?: boolean;
}

export interface Expense {
  id: string;
  categoryId: string;
  amount: number;
  date: string;
  notes?: string;
  image?: string; // base64
  createdAt: number;
}

export interface AppSettings {
  showImages: boolean;
  showNotes: boolean;
  isLocked: boolean;
  pinCode: string;
}

export enum ViewState {
  HOME = 'HOME',
  ADD_EXPENSE = 'ADD_EXPENSE',
  EDIT_EXPENSE = 'EDIT_EXPENSE',
  REPORTS = 'REPORTS',
  SETTINGS = 'SETTINGS',
  CATEGORY_DETAIL = 'CATEGORY_DETAIL'
}

import Dexie, { Table } from 'dexie';
import { Category, Expense, AppSettings } from './types';

export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;

  constructor() {
    super('SarfDB');
    this.version(1).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt',
      settings: 'id'
    });
  }
}

export const db = new SarfDB();

// Initialize default data if empty
export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true,
      isLocked: false,
      pinCode: ''
    }, 'app_settings');
  }
}

import React, { useState, useEffect } from 'react';
import { db, initializeDb } from './db';
import { ViewState, Category, Expense, AppSettings } from './types';
import { 
  Plus, 
  Home, 
  PieChart, 
  Settings as SettingsIcon, 
  Lock,
  ChevronRight,
  ChevronLeft
} from 'lucide-react';

// View Components
import HomeView from './components/HomeView';
import AddExpenseView from './components/AddExpenseView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import CategoryDetailView from './components/CategoryDetailView';
import LockScreen from './components/LockScreen';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [isLocked, setIsLocked] = useState<boolean>(false);
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [initialized, setInitialized] = useState(false);

  useEffect(() => {
    const init = async () => {
      await initializeDb();
      const s = await db.settings.get('app_settings');
      if (s) {
        setSettings(s);
        if (s.isLocked) {
          setIsLocked(true);
        }
      }
      setInitialized(true);
    };
    init();
  }, []);

  if (!initialized || !settings) return <div className="min-h-screen bg-slate-950 flex items-center justify-center text-white">جاري التحميل...</div>;

  if (isLocked) {
    return <LockScreen onUnlock={() => setIsLocked(false)} pinCode={settings.pinCode} />;
  }

  const renderView = () => {
    switch (currentView) {
      case ViewState.HOME:
        return <HomeView 
          onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} 
          onCategorySelect={(cat) => {
            setSelectedCategory(cat);
            setCurrentView(ViewState.CATEGORY_DETAIL);
          }}
        />;
      case ViewState.ADD_EXPENSE:
        return <AddExpenseView 
          onClose={() => setCurrentView(ViewState.HOME)} 
          initialData={editingExpense}
        />;
      case ViewState.REPORTS:
        return <ReportsView />;
      case ViewState.SETTINGS:
        return <SettingsView onUpdateSettings={setSettings} />;
      case ViewState.CATEGORY_DETAIL:
        return selectedCategory ? (
          <CategoryDetailView 
            category={selectedCategory} 
            onBack={() => setCurrentView(ViewState.HOME)}
            onEditExpense={(exp) => {
              setEditingExpense(exp);
              setCurrentView(ViewState.ADD_EXPENSE);
            }}
          />
        ) : <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => {
          setSelectedCategory(cat);
          setCurrentView(ViewState.CATEGORY_DETAIL);
        }} />;
      default:
        return <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => {
          setSelectedCategory(cat);
          setCurrentView(ViewState.CATEGORY_DETAIL);
        }} />;
    }
  };

  return (
    <div className="min-h-screen pb-20 max-w-md mx-auto bg-slate-950 text-slate-100 flex flex-col relative">
      <header className="p-4 flex justify-between items-center border-b border-slate-800 sticky top-0 bg-slate-950/80 backdrop-blur-md z-40">
        <h1 className="text-2xl font-bold text-blue-500">صرف</h1>
        <div className="flex gap-4">
          <button 
            onClick={() => setIsLocked(true)} 
            className="p-2 hover:bg-slate-800 rounded-full transition-colors"
          >
            <Lock size={20} className="text-slate-400" />
          </button>
        </div>
      </header>

      <main className="flex-grow p-4 overflow-y-auto">
        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-slate-900 border-t border-slate-800 flex justify-around p-3 z-50">
        <button 
          onClick={() => setCurrentView(ViewState.HOME)}
          className={`flex flex-col items-center gap-1 ${currentView === ViewState.HOME || currentView === ViewState.CATEGORY_DETAIL ? 'text-blue-500' : 'text-slate-500'}`}
        >
          <Home size={24} />
          <span className="text-xs">الرئيسية</span>
        </button>

        <button 
          onClick={() => {
            setEditingExpense(null);
            setCurrentView(ViewState.ADD_EXPENSE);
          }}
          className="bg-blue-600 p-4 rounded-full -mt-10 shadow-lg shadow-blue-900/40 text-white active:scale-90 transition-transform"
        >
          <Plus size={28} />
        </button>

        <button 
          onClick={() => setCurrentView(ViewState.REPORTS)}
          className={`flex flex-col items-center gap-1 ${currentView === ViewState.REPORTS ? 'text-blue-500' : 'text-slate-500'}`}
        >
          <PieChart size={24} />
          <span className="text-xs">التقارير</span>
        </button>

        <button 
          onClick={() => setCurrentView(ViewState.SETTINGS)}
          className={`flex flex-col items-center gap-1 ${currentView === ViewState.SETTINGS ? 'text-blue-500' : 'text-slate-500'}`}
        >
          <SettingsIcon size={24} />
          <span className="text-xs">الإعدادات</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Trash2, 
  Plus,
  GripVertical,
  MoreVertical
} from 'lucide-react';

interface HomeViewProps {
  onAdd: () => void;
  onCategorySelect: (cat: Category) => void;
}

const HomeView: React.FC<HomeViewProps> = ({ onAdd, onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');
  const [totalExpenses, setTotalExpenses] = useState(0);

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};
    let grandTotal = 0;

    expenses.forEach(exp => {
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;
      grandTotal += exp.amount;
    });

    setCategoryTotals(totals);
    setTotalExpenses(grandTotal);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleAddCategory = async () => {
    if (!newCategoryName.trim()) return;
    const id = Date.now().toString();
    const order = categories.length;
    await db.categories.add({
      id,
      name: newCategoryName,
      color: '#3b82f6',
      order
    });
    setNewCategoryName('');
    setIsAddingCategory(false);
    loadData();
  };

  const handleDeleteCategory = async (cat: Category) => {
    if (cat.isDefault) {
      alert('لا يمكن حذف القسم العام');
      return;
    }

    const count = await db.expenses.where('categoryId').equals(cat.id).count();
    if (count > 0) {
      const confirmMove = window.confirm(`هذا القسم يحتوي على ${count} مصروفات. هل تريد نقلها للقسم العام وحذف القسم؟`);
      if (confirmMove) {
        await db.expenses.where('categoryId').equals(cat.id).modify({ categoryId: 'default_general' });
        await db.categories.delete(cat.id);
        loadData();
      }
    } else {
      await db.categories.delete(cat.id);
      loadData();
    }
  };

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white text-center">
        <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي المصاريف</p>
        <h2 className="text-4xl font-bold mb-2 tabular-nums">
          {totalExpenses.toLocaleString('ar-SA')} 
          <span className="text-lg mr-2 opacity-80">ريال</span>
        </h2>
      </div>

      <div className="flex justify-between items-center px-1">
        <h3 className="text-lg font-bold text-slate-300">الأقسام</h3>
        <button 
          onClick={() => setIsAddingCategory(true)}
          className="text-blue-500 hover:bg-blue-500/10 p-2 rounded-full transition-colors flex items-center gap-1"
        >
          <FolderPlus size={20} />
          <span className="text-sm font-medium">قسم جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {categories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-2xl p-4 active:scale-95 transition-transform group relative cursor-pointer"
            onClick={() => onCategorySelect(cat)}
          >
            <div className="flex justify-between items-start mb-3">
              <div 
                className="w-3 h-3 rounded-full mt-1" 
                style={{ backgroundColor: cat.color }} 
              />
              {!cat.isDefault && (
                <button 
                  onClick={(e) => {
                    e.stopPropagation();
                    handleDeleteCategory(cat);
                  }}
                  className="text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
                >
                  <Trash2 size={16} />
                </button>
              )}
            </div>
            <h4 className="font-bold text-slate-200 truncate">{cat.name}</h4>
            <p className="text-slate-400 text-sm mt-1">
              {categoryTotals[cat.id] ? categoryTotals[cat.id].toLocaleString('ar-SA') : '٠'} ريال
            </p>
          </div>
        ))}
      </div>

      {isAddingCategory && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full rounded-2xl p-6 shadow-2xl">
            <h3 className="text-xl font-bold mb-4">إضافة قسم جديد</h3>
            <input 
              autoFocus
              className="w-full bg-slate-800 border border-slate-700 rounded-xl px-4 py-3 text-white mb-6 focus:ring-2 focus:ring-blue-500 outline-none"
              placeholder="اسم القسم..."
              value={newCategoryName}
              onChange={(e) => setNewCategoryName(e.target.value)}
            />
            <div className="flex gap-3">
              <button 
                onClick={handleAddCategory}
                className="flex-grow bg-blue-600 text-white font-bold py-3 rounded-xl hover:bg-blue-700 transition-colors"
              >
                إضافة
              </button>
              <button 
                onClick={() => setIsAddingCategory(false)}
                className="flex-grow bg-slate-800 text-slate-300 font-bold py-3 rounded-xl hover:bg-slate-700 transition-colors"
              >
                إلغاء
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default HomeView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Category, Expense } from '../types';
import { X, Camera, Calendar, Image as ImageIcon, Trash2 } from 'lucide-react';

interface AddExpenseViewProps {
  onClose: () => void;
  initialData?: Expense | null;
}

const AddExpenseView: React.FC<AddExpenseViewProps> = ({ onClose, initialData }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [amount, setAmount] = useState(initialData?.amount.toString() || '');
  const [categoryId, setCategoryId] = useState(initialData?.categoryId || 'default_general');
  const [notes, setNotes] = useState(initialData?.notes || '');
  const [date, setDate] = useState(initialData?.date || new Date().toISOString().split('T')[0]);
  const [image, setImage] = useState<string | null>(initialData?.image || null);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    db.categories.toArray().then(setCategories);
  }, []);

  const handleSave = async () => {
    const numAmount = parseFloat(amount);
    if (!numAmount || numAmount <= 0) {
      alert('الرجاء إدخال مبلغ صحيح أكبر من صفر');
      return;
    }

    const expenseData: Expense = {
      id: initialData?.id || Date.now().toString(),
      amount: numAmount,
      categoryId,
      notes,
      date,
      image: image || undefined,
      createdAt: initialData?.createdAt || Date.now()
    };

    if (initialData) {
      await db.expenses.put(expenseData);
    } else {
      await db.expenses.add(expenseData);
    }
    onClose();
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="space-y-6 pb-20">
      <div className="flex items-center justify-between mb-2">
        <h2 className="text-xl font-bold">{initialData ? 'تعديل مصروف' : 'إضافة مصروف'}</h2>
        <button onClick={onClose} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700">
          <X size={20} />
        </button>
      </div>

      <div className="space-y-4">
        <div>
          <label className="block text-slate-400 text-sm mb-2">المبلغ (ريال)</label>
          <input 
            type="number" 
            pattern="[0-9]*"
            inputMode="decimal"
            autoFocus
            className="w-full bg-slate-900 border border-slate-700 rounded-2xl px-4 py-6 text-4xl font-bold text-center text-blue-500 outline-none focus:ring-2 focus:ring-blue-500 tabular-nums"
            value={amount}
            onChange={(e) => setAmount(e.target.value)}
            placeholder="0.00"
          />
        </div>

        <div>
          <label className="block text-slate-400 text-sm mb-2">القسم</label>
          <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
            {categories.map(cat => (
              <button
                key={cat.id}
                onClick={() => setCategoryId(cat.id)}
                className={`flex-shrink-0 px-5 py-2 rounded-full border transition-all ${
                  categoryId === cat.id 
                    ? 'bg-blue-600 border-blue-600 text-white font-bold' 
                    : 'bg-slate-900 border-slate-700 text-slate-400'
                }`}
              >
                {cat.name}
              </button>
            ))}
          </div>
        </div>

        <div>
          <label className="block text-slate-400 text-sm mb-2">التاريخ</label>
          <div className="relative">
            <input 
              type="date"
              className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500"
              value={date}
              onChange={(e) => setDate(e.target.value)}
            />
            <Calendar className="absolute left-3 top-3 text-slate-500 pointer-events-none" size={20} />
          </div>
        </div>

        <div>
          <label className="block text-slate-400 text-sm mb-2">ملاحظات (اختياري)</label>
          <textarea 
            className="w-full bg-slate-900 border border-slate-700 rounded-xl px-4 py-3 outline-none focus:ring-2 focus:ring-blue-500 resize-none h-24"
            placeholder="اكتب تفاصيل المصروف هنا..."
            value={notes}
            onChange={(e) => setNotes(e.target.value)}
          />
        </div>

        <div>
          <label className="block text-slate-400 text-sm mb-2">إرفاق صورة</label>
          {image ? (
            <div className="relative group rounded-xl overflow-hidden border border-slate-700 aspect-video bg-slate-900">
              <img src={image} className="w-full h-full object-contain" alt="Expense attachment" />
              <button 
                onClick={() => setImage(null)}
                className="absolute top-2 right-2 bg-red-600 text-white p-2 rounded-full shadow-lg opacity-0 group-hover:opacity-100 transition-opacity"
              >
                <Trash2 size={16} />
              </button>
            </div>
          ) : (
            <button 
              onClick={() => fileInputRef.current?.click()}
              className="w-full border-2 border-dashed border-slate-700 rounded-xl p-8 flex flex-col items-center justify-center gap-2 text-slate-500 hover:border-blue-500 hover:text-blue-500 transition-all active:scale-95"
            >
              <Camera size={32} />
              <span className="font-medium text-sm">تصوير فاتورة أو اختيار ملف</span>
            </button>
          )}
          <input 
            type="file" 
            ref={fileInputRef} 
            className="hidden" 
            accept="image/*" 
            onChange={handleImageUpload} 
          />
        </div>
      </div>

      <div className="pt-4 flex gap-3">
        <button 
          onClick={handleSave}
          className="flex-grow bg-blue-600 text-white font-bold py-4 rounded-2xl shadow-lg shadow-blue-900/30 active:scale-95 transition-all text-lg"
        >
          حفظ المصروف
        </button>
        {initialData && (
          <button 
            onClick={async () => {
              if (window.confirm('هل أنت متأكد من حذف هذا المصروف؟')) {
                await db.expenses.delete(initialData.id);
                onClose();
              }
            }}
            className="p-4 bg-red-600/20 text-red-500 rounded-2xl hover:bg-red-600 hover:text-white transition-all"
          >
            <Trash2 size={24} />
          </button>
        )}
      </div>
    </div>
  );
};

export default AddExpenseView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category, Expense } from '../types';
import { ChevronRight, Filter, Search, Calendar, FileText, Image as ImageIcon } from 'lucide-react';

interface CategoryDetailViewProps {
  category: Category;
  onBack: () => void;
  onEditExpense: (exp: Expense) => void;
}

const CategoryDetailView: React.FC<CategoryDetailViewProps> = ({ category, onBack, onEditExpense }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [search, setSearch] = useState('');
  const [total, setTotal] = useState(0);

  useEffect(() => {
    const load = async () => {
      let exps = await db.expenses.where('categoryId').equals(category.id).toArray();
      exps.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      setExpenses(exps);
      setTotal(exps.reduce((acc, curr) => acc + curr.amount, 0));
    };
    load();
  }, [category.id]);

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(search.toLowerCase()) || 
    exp.amount.toString().includes(search)
  );

  return (
    <div className="space-y-6">
      <div className="flex items-center gap-4 mb-2">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700">
          <ChevronRight size={20} />
        </button>
        <h2 className="text-xl font-bold">{category.name}</h2>
      </div>

      <div className="bg-slate-900 p-6 rounded-3xl border border-slate-800 text-center">
        <p className="text-slate-400 text-sm mb-1">إجمالي القسم</p>
        <h3 className="text-3xl font-bold tabular-nums">
          {total.toLocaleString('ar-SA')} <span className="text-base text-slate-500">ريال</span>
        </h3>
      </div>

      <div className="relative">
        <Search className="absolute right-3 top-3 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-xl pr-10 pl-4 py-3 text-sm focus:ring-1 focus:ring-blue-500 outline-none"
          placeholder="بحث في المصروفات..."
          value={search}
          onChange={(e) => setSearch(e.target.value)}
        />
      </div>

      <div className="space-y-3">
        {filteredExpenses.map((exp, idx) => (
          <div 
            key={exp.id} 
            className="bg-slate-900/50 border border-slate-800/50 rounded-2xl p-4 flex justify-between items-center active:bg-slate-800 transition-colors cursor-pointer"
            onClick={() => onEditExpense(exp)}
          >
            <div className="flex gap-4 items-center">
              <div className="w-10 h-10 rounded-xl bg-blue-600/10 flex items-center justify-center text-blue-500 font-bold text-sm">
                {idx + 1}
              </div>
              <div>
                <h4 className="font-bold tabular-nums">{exp.amount.toLocaleString('ar-SA')} ريال</h4>
                <div className="flex gap-2 items-center text-xs text-slate-500 mt-1">
                  <Calendar size={12} />
                  <span>{exp.date}</span>
                  {exp.notes && <FileText size={12} className="mr-1" />}
                  {exp.image && <ImageIcon size={12} className="mr-1" />}
                </div>
              </div>
            </div>
            <ChevronRight size={18} className="text-slate-700 rotate-180" />
          </div>
        ))}
        {filteredExpenses.length === 0 && (
          <div className="text-center py-10 text-slate-600">
            <p>لا توجد مصروفات مسجلة</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default CategoryDetailView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  FileDown, 
  Filter, 
  Calendar, 
  ChevronDown, 
  Share2,
  TrendingUp,
  BarChart3
} from 'lucide-react';

const ReportsView: React.FC = () => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [sortBy, setSortBy] = useState<'date' | 'amount'>('date');

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let q = db.expenses.where('date').between(fromDate, toDate, true, true);
      let results = await q.toArray();

      if (selectedCategoryId !== 'all') {
        results = results.filter(e => e.categoryId === selectedCategoryId);
      }

      if (sortBy === 'date') {
        results.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      } else {
        results.sort((a, b) => b.amount - a.amount);
      }

      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId, sortBy]);

  const generatePDF = () => {
    alert('تصدير PDF يتطلب مكتبة jsPDF. في هذا النموذج، يتم عرض البيانات فقط.');
    console.table(expenses);
  };

  const total = expenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1">من تاريخ</label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
          />
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1">إلى تاريخ</label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
          />
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
        <button 
          onClick={() => setSelectedCategoryId('all')}
          className={`px-4 py-2 rounded-xl text-xs font-bold transition-all ${selectedCategoryId === 'all' ? 'bg-blue-600' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
        >
          الكل
        </button>
        {categories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => setSelectedCategoryId(cat.id)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === cat.id ? 'bg-blue-600' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
          >
            {cat.name}
          </button>
        ))}
      </div>

      <div className="bg-blue-600 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white flex justify-between items-center">
        <div>
          <p className="text-blue-100 text-sm mb-1">إجمالي الفترة</p>
          <h3 className="text-2xl font-bold tabular-nums">{total.toLocaleString('ar-SA')} ريال</h3>
        </div>
        <div className="p-3 bg-white/10 rounded-2xl">
          <TrendingUp size={24} />
        </div>
      </div>

      <div className="flex justify-between items-center">
        <h4 className="font-bold text-slate-400">التفاصيل</h4>
        <div className="flex gap-2">
          <button 
            onClick={() => setSortBy(sortBy === 'date' ? 'amount' : 'date')}
            className="p-2 bg-slate-900 border border-slate-800 rounded-lg text-xs text-blue-500 flex items-center gap-1"
          >
            {sortBy === 'date' ? 'حسب التاريخ' : 'حسب المبلغ'}
          </button>
          <button 
            onClick={generatePDF}
            className="p-2 bg-slate-900 border border-slate-800 rounded-lg text-xs text-green-500 flex items-center gap-1"
          >
            <FileDown size={14} />
            <span>PDF</span>
          </button>
        </div>
      </div>

      <div className="space-y-2">
        {expenses.map((exp, i) => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/40 p-3 rounded-xl flex justify-between items-center border border-slate-800/50">
              <div className="flex gap-3 items-center">
                <span className="text-[10px] text-slate-600 font-mono w-4">{i + 1}</span>
                <div>
                  <p className="text-sm font-bold tabular-nums">{exp.amount.toLocaleString('ar-SA')} ريال</p>
                  <p className="text-[10px] text-slate-500">{exp.date} • {cat?.name || 'غير معروف'}</p>
                </div>
              </div>
              <div className="text-[10px] text-slate-600 bg-slate-800 px-2 py-1 rounded">
                {exp.notes ? 'ملاحظة' : ''} {exp.image ? '• صورة' : ''}
              </div>
            </div>
          );
        })}
        {expenses.length === 0 && (
          <div className="text-center py-20 text-slate-600 flex flex-col items-center gap-4">
            <BarChart3 size={48} className="opacity-20" />
            <p>لا توجد بيانات للفترة المحددة</p>
          </div>
        )}
      </div>
    </div>
  );
};

export default ReportsView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { AppSettings } from '../types';
import { 
  Lock, 
  Eye, 
  EyeOff, 
  Download, 
  Upload, 
  ChevronLeft,
  Shield,
  Palette,
  Database,
  Trash2
} from 'lucide-react';

interface SettingsViewProps {
  onUpdateSettings: (s: AppSettings) => void;
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [showPinInput, setShowPinInput] = useState(false);
  const [tempPin, setTempPin] = useState('');

  useEffect(() => {
    db.settings.get('app_settings').then(s => {
      if (s) setSettings(s);
    });
  }, []);

  const updateSetting = async (key: keyof AppSettings, value: any) => {
    if (!settings) return;
    const newSettings = { ...settings, [key]: value };
    await db.settings.put(newSettings, 'app_settings');
    setSettings(newSettings);
    onUpdateSettings(newSettings);
  };

  const exportData = async () => {
    const cats = await db.categories.toArray();
    const exps = await db.expenses.toArray();
    const sets = await db.settings.get('app_settings');

    const data = JSON.stringify({ cats, exps, sets });
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `sarf_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (window.confirm('سيتم مسح البيانات الحالية واستبدالها بالنسخة الاحتياطية. هل أنت متأكد؟')) {
          await db.categories.clear();
          await db.expenses.clear();
          await db.categories.bulkAdd(data.cats);
          await db.expenses.bulkAdd(data.exps);
          alert('تم استيراد البيانات بنجاح!');
          window.location.reload();
        }
      } catch (err) {
        alert('خطأ في ملف النسخة الاحتياطية');
      }
    };
    reader.readAsText(file);
  };

  const handleToggleLock = () => {
    if (settings?.isLocked) {
      updateSetting('isLocked', false);
      updateSetting('pinCode', '');
    } else {
      setShowPinInput(true);
    }
  };

  const handleSetPin = () => {
    if (tempPin.length < 4) {
      alert('الرمز السري يجب أن يكون ٤ أرقام على الأقل');
      return;
    }
    updateSetting('pinCode', tempPin);
    updateSetting('isLocked', true);
    setShowPinInput(false);
    setTempPin('');
  };

  if (!settings) return null;

  return (
    <div className="space-y-6">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>

      <section className="space-y-2">
        <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider px-2">العرض</h3>
        <div className="bg-slate-900 rounded-2xl border border-slate-800 divide-y divide-slate-800">
          <div className="p-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <Eye size={20} className="text-slate-400" />
              <span>إظهار الملاحظات</span>
            </div>
            <button 
              onClick={() => updateSetting('showNotes', !settings.showNotes)}
              className={`w-12 h-6 rounded-full transition-colors relative ${settings.showNotes ? 'bg-blue-600' : 'bg-slate-700'}`}
            >
              <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${settings.showNotes ? 'left-1' : 'left-7'}`} />
            </button>
          </div>
          <div className="p-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <Palette size={20} className="text-slate-400" />
              <span>إظهار الصور في القوائم</span>
            </div>
            <button 
              onClick={() => updateSetting('showImages', !settings.showImages)}
              className={`w-12 h-6 rounded-full transition-colors relative ${settings.showImages ? 'bg-blue-600' : 'bg-slate-700'}`}
            >
              <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${settings.showImages ? 'left-1' : 'left-7'}`} />
            </button>
          </div>
        </div>
      </section>

      <section className="space-y-2">
        <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider px-2">الأمان</h3>
        <div className="bg-slate-900 rounded-2xl border border-slate-800 p-4 flex justify-between items-center">
          <div className="flex items-center gap-3">
            <Shield size={20} className="text-slate-400" />
            <div>
              <p>قفل التطبيق (PIN)</p>
              <p className="text-[10px] text-slate-500">يتطلب رمز دخول عند فتح التطبيق</p>
            </div>
          </div>
          <button 
            onClick={handleToggleLock}
            className={`w-12 h-6 rounded-full transition-colors relative ${settings.isLocked ? 'bg-blue-600' : 'bg-slate-700'}`}
          >
            <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${settings.isLocked ? 'left-1' : 'left-7'}`} />
          </button>
        </div>
        {showPinInput && (
          <div className="bg-blue-900/20 border border-blue-500/30 rounded-2xl p-4 space-y-3">
            <p className="text-sm font-bold text-blue-400">أدخل الرمز السري الجديد:</p>
            <input 
              type="password"
              maxLength={6}
              className="w-full bg-slate-950 border border-slate-800 rounded-xl px-4 py-2 text-center text-lg tracking-widest outline-none focus:ring-1 focus:ring-blue-500"
              value={tempPin}
              onChange={(e) => setTempPin(e.target.value)}
            />
            <button 
              onClick={handleSetPin}
              className="w-full bg-blue-600 text-white py-2 rounded-xl font-bold"
            >
              تفعيل القفل
            </button>
          </div>
        )}
      </section>

      <section className="space-y-2">
        <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider px-2">البيانات</h3>
        <div className="bg-slate-900 rounded-2xl border border-slate-800 divide-y divide-slate-800">
          <button 
            onClick={exportData}
            className="w-full p-4 flex items-center gap-3 hover:bg-slate-800/50 transition-colors text-left"
          >
            <Download size={20} className="text-blue-400" />
            <div className="text-right">
              <p>تصدير نسخة احتياطية</p>
              <p className="text-[10px] text-slate-500">حفظ جميع البيانات والصور في ملف خارجي</p>
            </div>
          </button>
          <label className="w-full p-4 flex items-center gap-3 hover:bg-slate-800/50 transition-colors cursor-pointer">
            <Upload size={20} className="text-green-400" />
            <div className="text-right flex-grow">
              <p>استيراد نسخة احتياطية</p>
              <p className="text-[10px] text-slate-500">استعادة البيانات من ملف محفظ مسبقاً</p>
            </div>
            <input type="file" className="hidden" accept=".json" onChange={importData} />
          </label>
          <button 
            onClick={async () => {
              if (window.confirm('سيتم حذف جميع المصروفات بشكل نهائي. هل أنت متأكد؟')) {
                await db.expenses.clear();
                alert('تم مسح جميع البيانات');
                window.location.reload();
              }
            }}
            className="w-full p-4 flex items-center gap-3 hover:bg-red-900/20 transition-colors text-red-500"
          >
            <Trash2 size={20} />
            <span>مسح جميع المصروفات</span>
          </button>
        </div>
      </section>

      <div className="text-center pt-4 opacity-30">
        <p className="text-xs">تطبيق صرف v1.0.0</p>
        <p className="text-[10px]">صنع بكل حب لتتبع مصاريفك</p>
      </div>
    </div>
  );
};

export default SettingsView;

import React, { useState } from 'react';
import { Lock, Delete, ChevronRight } from 'lucide-react';

interface LockScreenProps {
  onUnlock: () => void;
  pinCode: string;
}

const LockScreen: React.FC<LockScreenProps> = ({ onUnlock, pinCode }) => {
  const [input, setInput] = useState('');
  const [error, setError] = useState(false);

  const handlePress = (num: string) => {
    setError(false);
    if (input.length < pinCode.length) {
      const newInput = input + num;
      setInput(newInput);

      if (newInput.length === pinCode.length) {
        if (newInput === pinCode) {
          onUnlock();
        } else {
          setError(true);
          setTimeout(() => setInput(''), 500);
        }
      }
    }
  };

  const handleDelete = () => {
    setInput(input.slice(0, -1));
  };

  return (
    <div className="fixed inset-0 bg-slate-950 flex flex-col items-center justify-center z-[100] p-8">
      <div className="mb-12 flex flex-col items-center gap-4">
        <div className={`p-6 rounded-full ${error ? 'bg-red-600/20 text-red-500' : 'bg-blue-600/20 text-blue-500'}`}>
          <Lock size={48} />
        </div>
        <h2 className="text-2xl font-bold">صرف</h2>
        <p className="text-slate-400">أدخل الرمز السري للدخول</p>
      </div>

      <div className="flex gap-4 mb-12">
        {Array.from({ length: pinCode.length }).map((_, i) => (
          <div 
            key={i} 
            className={`w-4 h-4 rounded-full border-2 transition-all ${
              i < input.length ? 'bg-blue-500 border-blue-500' : 'bg-transparent border-slate-700'
            } ${error ? 'bg-red-500 border-red-500 animate-pulse' : ''}`}
          />
        ))}
      </div>

      <div className="grid grid-cols-3 gap-6 max-w-xs w-full">
        {[1, 2, 3, 4, 5, 6, 7, 8, 9, '', 0, 'del'].map((val, i) => {
          if (val === '') return <div key={i} />;
          if (val === 'del') {
            return (
              <button 
                key={i}
                onClick={handleDelete}
                className="w-16 h-16 rounded-full bg-slate-900 border border-slate-800 flex items-center justify-center text-slate-400 active:bg-slate-800 transition-colors"
              >
                <Delete size={24} />
              </button>
            );
          }
          return (
            <button 
              key={i}
              onClick={() => handlePress(val.toString())}
              className="w-16 h-16 rounded-full bg-slate-900 border border-slate-800 flex items-center justify-center text-2xl font-bold active:bg-blue-600 active:text-white transition-colors tabular-nums"
            >
              {val}
            </button>
          );
        })}
      </div>
    </div>
  );
};

export default LockScreen;

import { Dexie, type Table } from 'dexie';
import { Category, Expense, AppSettings } from './types';

// Using named import for Dexie ensures that the class and its prototype methods like version() 
// are correctly inherited and recognized by the TypeScript compiler.
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;

  constructor() {
    super('SarfDB');
    // Defining the schema using versioning; the 'version' method is inherited from the Dexie base class.
    this.version(1).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt',
      settings: 'id'
    });
  }
}

export const db = new SarfDB();

// Initialize default data if empty
export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true,
      isLocked: false,
      pinCode: ''
    }, 'app_settings');
  }
}

