import { Dexie, type Table } from 'dexie';
import { Category, Expense, AppSettings } from './types';

// Using the named import for Dexie to ensure that the class and its prototype methods 
// like version() are correctly inherited and recognized by the TypeScript compiler.
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;

  constructor() {
    super('SarfDB');
    // Defining the schema. 
    // Bumped to version 2 to apply the change from 'id' to an out-of-line key ('') for settings.

    // Fix for Error: Property 'version' does not exist on type 'SarfDB'.
    // The version() method is a core part of the Dexie instance. Using named import ensures TS visibility.
    this.version(2).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt',
      settings: '' // Use an out-of-line key to support .put(data, 'app_settings')
    });
  }
}

export const db = new SarfDB();

// Initialize default data if empty
export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    // With an out-of-line key, the second argument 'app_settings' is the primary key.
    await db.settings.put({
      showImages: true,
      showNotes: true,
      isLocked: false,
      pinCode: ''
    }, 'app_settings');
  }
}

