          <label className="block text-xs text-slate-500 mb-1">إلى تاريخ</label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
          />
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
        <button 
          onClick={() => setSelectedCategoryId('all')}
          className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === 'all' ? 'bg-blue-600 text-white' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
        >
          الكل
        </button>
        {categories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => setSelectedCategoryId(cat.id)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === cat.id ? 'bg-blue-600 text-white' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
          >
            {cat.name}
          </button>
        ))}
      </div>

      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white flex justify-between items-center">
        <div>
          <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الفترة المختارة</p>
          <h3 className="text-2xl font-bold tabular-nums">{total.toLocaleString('ar-SA')} ريال</h3>
        </div>
        <div className="p-3 bg-white/20 rounded-2xl">
          <TrendingUp size={24} />
        </div>
      </div>

      <div className="flex justify-between items-center">
        <h4 className="font-bold text-slate-400">سجل المصروفات</h4>
        <div className="flex gap-2">
          <button 
            onClick={() => setSortBy(sortBy === 'date' ? 'amount' : 'date')}
            className="px-3 py-2 bg-slate-900 border border-slate-800 rounded-xl text-xs text-blue-400 font-bold active:scale-95 transition-transform"
          >
            {sortBy === 'date' ? 'ترتيب: التاريخ' : 'ترتيب: المبلغ'}
          </button>
          <button 
            disabled={expenses.length === 0 || isGenerating}
            onClick={generatePDF}
            className={`px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 transition-all active:scale-95 ${isGenerating ? 'bg-slate-800 text-slate-500' : 'bg-green-600 text-white hover:bg-green-700'}`}
          >
            {isGenerating ? (
              <Loader2 size={16} className="animate-spin" />
            ) : (
              <FileDown size={16} />
            )}
            <span>تحميل PDF</span>
          </button>
        </div>
      </div>

      <div className="space-y-3">
        {expenses.map((exp, i) => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30">
              <div className="flex gap-4 items-center">
                <div className="w-8 h-8 rounded-lg bg-slate-800 flex items-center justify-center text-[10px] text-slate-500 font-mono">
                  {i + 1}
                </div>
                <div>
                  <p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString('ar-SA')} ريال</p>
                  <p className="text-xs text-slate-500 mt-0.5">{exp.date} • {cat?.name || 'قسم عام'}</p>
                </div>
              </div>
              {exp.notes && (
                <div className="text-[10px] px-2 py-1 bg-blue-500/10 text-blue-400 rounded-lg max-w-[100px] truncate">
                  {exp.notes}
                </div>
              )}
            </div>
          );
        })}
        {expenses.length === 0 && (
          <div className="text-center py-20 text-slate-600 flex flex-col items-center gap-4">
            <BarChart3 size={48} className="opacity-10" />
            <p className="font-medium">لا توجد مصروفات في هذه الفترة</p>
          </div>
        )}
      </div>

      <div 
        ref={reportRef} 
        dir="rtl"
        style={{ 
          display: 'none', 
          width: '210mm', 
          padding: '20mm', 
          backgroundColor: 'white', 
          color: 'black',
          position: 'fixed',
          top: 0,
          left: '-5000px'
        }}
      >
        <div style={{ borderBottom: '2px solid #3b82f6', paddingBottom: '10px', marginBottom: '20px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h1 style={{ fontSize: '24px', fontWeight: 'bold', color: '#3b82f6', margin: 0 }}>تقرير مصروفات (صرف)</h1>
            <p style={{ fontSize: '12px', color: '#64748b', marginTop: '5px' }}>تاريخ الاستخراج: {new Date().toLocaleDateString('ar-SA')}</p>
          </div>
          <div style={{ textAlign: 'left' }}>
            <p style={{ fontWeight: 'bold', fontSize: '14px', margin: 0 }}>الفترة:</p>
            <p style={{ fontSize: '12px', margin: 0 }}>{fromDate} - {toDate}</p>
          </div>
        </div>

        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '20px', marginBottom: '30px' }}>
          <div style={{ padding: '15px', backgroundColor: '#f8fafc', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
            <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '5px' }}>إجمالي المصروفات</p>
            <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#1e293b', margin: 0 }}>{total.toLocaleString('ar-SA')} ريال</h2>
          </div>
          <div style={{ padding: '15px', backgroundColor: '#f8fafc', borderRadius: '10px', border: '1px solid #e2e8f0' }}>
            <p style={{ fontSize: '12px', color: '#64748b', marginBottom: '5px' }}>عدد العمليات</p>
            <h2 style={{ fontSize: '24px', fontWeight: 'bold', color: '#1e293b', margin: 0 }}>{expenses.length}</h2>
          </div>
        </div>

        <table style={{ width: '100%', borderCollapse: 'collapse', fontSize: '12px' }}>
          <thead>
            <tr style={{ backgroundColor: '#3b82f6', color: 'white' }}>
              <th style={{ padding: '8px', textAlign: 'right', border: '1px solid #e2e8f0' }}>#</th>
              <th style={{ padding: '8px', textAlign: 'right', border: '1px solid #e2e8f0' }}>التاريخ</th>
              <th style={{ padding: '8px', textAlign: 'right', border: '1px solid #e2e8f0' }}>القسم</th>
              <th style={{ padding: '8px', textAlign: 'right', border: '1px solid #e2e8f0' }}>الملاحظات</th>
              <th style={{ padding: '8px', textAlign: 'left', border: '1px solid #e2e8f0' }}>المبلغ</th>
            </tr>
          </thead>
          <tbody>
            {expenses.map((exp, idx) => {
              const cat = categories.find(c => c.id === exp.categoryId);
              return (
                <tr key={exp.id} style={{ backgroundColor: idx % 2 === 0 ? 'white' : '#f8fafc' }}>
                  <td style={{ padding: '8px', border: '1px solid #e2e8f0' }}>{idx + 1}</td>
                  <td style={{ padding: '8px', border: '1px solid #e2e8f0' }}>{exp.date}</td>
                  <td style={{ padding: '8px', border: '1px solid #e2e8f0' }}>{cat?.name || 'عام'}</td>
                  <td style={{ padding: '8px', border: '1px solid #e2e8f0' }}>{exp.notes || '-'}</td>
                  <td style={{ padding: '8px', border: '1px solid #e2e8f0', fontWeight: 'bold', textAlign: 'left' }}>{exp.amount.toLocaleString('ar-SA')} ر.س</td>
