            className="px-3 py-2 bg-slate-900 border border-slate-800 rounded-xl text-xs text-blue-400 font-bold active:scale-95 transition-transform"
          >
            {sortBy === 'date' ? 'ترتيب: التاريخ' : 'ترتيب: المبلغ'}
          </button>
          <button 
            disabled={expenses.length === 0 || isGenerating}
            onClick={generatePDF}
            className={`px-4 py-2 rounded-xl text-xs font-bold flex items-center gap-2 transition-all active:scale-95 ${isGenerating ? 'bg-slate-800 text-slate-500' : 'bg-green-600 text-white hover:bg-green-700'}`}
          >
            {isGenerating ? (
              <Loader2 size={16} className="animate-spin" />
            ) : (
              <FileDown size={16} />
            )}
            <span>تحميل PDF</span>
          </button>
        </div>
      </div>

      <div className="space-y-3">
        {expenses.map((exp, i) => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div key={exp.id} className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30">
              <div className="flex gap-4 items-center">
                <div className="w-8 h-8 rounded-lg bg-slate-800 flex items-center justify-center text-[10px] text-slate-500 font-mono">
                  {i + 1}
                </div>
                <div>
                  <p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString('ar-SA')} ريال</p>
                  <p className="text-xs text-slate-500 mt-0.5">{exp.date} • {cat?.name || 'قسم عام'}</p>
                </div>
              </div>
              {exp.notes && (
                <div className="text-[10px] px-2 py-1 bg-blue-500/10 text-blue-400 rounded-lg max-w-[100px] truncate">
                  {exp.notes}
                </div>
              )}
            </div>
          );
        })}
        {expenses.length === 0 && (
          <div className="text-center py-20 text-slate-600 flex flex-col items-center gap-4">
            <BarChart3 size={48} className="opacity-10" />
            <p className="font-medium">لا توجد مصروفات في هذه الفترة</p>
          </div>
        )}
      </div>

      {/* قالب الـ PDF المخفي - تم تحسينه لضمان ظهور الجداول والصور */}
      <div 
        ref={reportRef} 
        dir="rtl"
        style={{ 
          display: 'none', 
          width: '210mm', 
          padding: '15mm', 
          backgroundColor: 'white', 
          color: 'black',
          position: 'fixed',
          top: 0,
          left: '-5000px',
          fontFamily: 'Tajawal, sans-serif'
        }}
      >
        {/* الهيدر */}
        <div style={{ borderBottom: '3px solid #3b82f6', paddingBottom: '15px', marginBottom: '25px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <div>
            <h1 style={{ fontSize: '28px', fontWeight: 'bold', color: '#3b82f6', margin: 0 }}>كشف مصروفات تفصيلي</h1>
            <p style={{ fontSize: '12px', color: '#64748b', marginTop: '5px' }}>تطبيق "صرف" - تم الاستخراج في: {new Date().toLocaleDateString('ar-SA')}</p>
          </div>
          <div style={{ textAlign: 'left' }}>
            <p style={{ fontWeight: 'bold', fontSize: '14px', margin: 0 }}>الفترة الزمنية:</p>
            <p style={{ fontSize: '12px', color: '#1e293b', margin: 0 }}>{fromDate} إلى {toDate}</p>
          </div>
        </div>

        {/* ملخص الإجماليات */}
        <div style={{ display: 'grid', gridTemplateColumns: '1fr 1fr', gap: '15px', marginBottom: '30px' }}>
          <div style={{ padding: '20px', backgroundColor: '#eff6ff', borderRadius: '12px', border: '1px solid #bfdbfe', textAlign: 'center' }}>
            <p style={{ fontSize: '14px', color: '#1e40af', marginBottom: '8px' }}>إجمالي المبلغ</p>
            <h2 style={{ fontSize: '32px', fontWeight: 'bold', color: '#1e3a8a', margin: 0 }}>{total.toLocaleString('ar-SA')} ريال</h2>
