import { Dexie } from 'dexie';
import type { Table } from 'dexie';
import { Category, Expense, AppSettings } from './types';

// Fix: Using named import for Dexie ensures the 'version' method and other instance properties are correctly inherited and recognized by TypeScript
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;

  constructor() {
    super('SarfDB');

    // Fix: Property 'version' exists on the Dexie base class; named imports ensure proper prototype chain typing
    // Version 2 fixed the settings store to use out-of-line keys
    this.version(2).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt',
      settings: '' 
    });
  }
}

export const db = new SarfDB();

export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true,
      isLocked: false,
      pinCode: ''
    }, 'app_settings');
  }
}

