              </div>
            </div>
            <ChevronRight size={18} className="text-slate-700 rotate-180" />
          </div>
        ))}
        {filteredExpenses.length === 0 && (
          <div className="text-center py-10 text-slate-600">
            <p>لا توجد مصروفات مسجلة</p>
          </div>
        )}
