    const whatsappUrl = `https://wa.me/967${category.phoneNumber}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');

    // إشعار للمستخدم
    setTimeout(() => {
      alert('سيتم فتح واتساب الآن. يرجى إرسال الرسالة ثم إرفاق ملف الـ PDF يدوياً من جهازك.');
    }, 500);
  };

  const total = expenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            من تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
          />
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            إلى تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
          />
        </div>
      </div>

      <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
        <button 
          onClick={() => setSelectedCategoryId('all')}
          className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === 'all' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
        >
          الكل
        </button>
        {categories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => setSelectedCategoryId(cat.id)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === cat.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
          >
            {cat.name}
          </button>
        ))}
      </div>

