              <FileDown size={24} className="text-blue-500" />
            )}
            <span className="text-xs">تحميل PDF</span>
          </button>

          <button 
            disabled={expenses.length === 0 || isGenerating || selectedCategoryId === 'all' || !categories.find(c => c.id === selectedCategoryId)?.phoneNumber}
            onClick={shareViaWhatsApp}
            className={`px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 transition-all active:scale-95 ${expenses.length === 0 || selectedCategoryId === 'all' || !categories.find(c => c.id === selectedCategoryId)?.phoneNumber ? 'bg-slate-800 text-slate-600 opacity-50 grayscale' : 'bg-green-600/10 border border-green-600/30 text-green-500 hover:bg-green-600 hover:text-white'}`}
          >
            <MessageCircle size={24} />
            <span className="text-xs">مشاركة واتساب</span>
          </button>
        </div>
      </div>

      <div className="space-y-3">
        <div className="flex justify-between items-center px-1">
          <h4 className="font-bold text-slate-400 text-sm">سجل المصروفات</h4>
        </div>
        {expenses.slice().reverse().map((exp, i) => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div 
              key={exp.id} 
              className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-colors"
              onClick={() => onExpenseSelect?.(exp)}
            >
              <div className="flex gap-4 items-center overflow-hidden">
                <div className="w-8 h-8 flex-shrink-0 rounded-lg bg-slate-800 flex items-center justify-center text-[10px] text-slate-500 font-mono">
