                <div className="overflow-hidden">
                  <p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString('ar-SA')} ريال</p>
                  <p className="text-[10px] text-slate-500 mt-0.5 truncate">{exp.date} • {cat?.name || 'عام'}</p>
                </div>
              </div>
              {/* Chevron icon added to lucide-react imports to fix 'ChevronRight' not found error */}
