import Dexie, { type Table } from 'dexie';
import { Category, Expense, AppSettings } from './types';

// Define the database class extending Dexie
// Using the default import for Dexie is the most compatible way to ensure 
// inherited methods like 'version' are correctly recognized by the TypeScript compiler.
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;

  constructor() {
    super('SarfDB');
    // Define the schema inside the constructor as recommended for Dexie with TypeScript.
    // Using this.version() to define the database version and schema.
    this.version(2).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt',
      settings: '' 
    });
  }
}

export const db = new SarfDB();

export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true
    }, 'app_settings');
  }
}

export interface Category {
  id: string;
  name: string;
  color: string;
  order: number;
  phoneNumber?: string; // حقل اختياري لرقم الهاتف
  isDefault?: boolean;
}

export interface Expense {
  id: string;
  categoryId: string;
  amount: number;
  date: string;
  notes?: string;
  image?: string; // base64
  createdAt: number;
  serialNumber?: number; // رقم تسلسلي (SRF-1)
}

export interface AppSettings {
  showImages: boolean;
  showNotes: boolean;
}

