  HOME = 'HOME',
  ADD_EXPENSE = 'ADD_EXPENSE',
  EDIT_EXPENSE = 'EDIT_EXPENSE',
  REPORTS = 'REPORTS',
  SETTINGS = 'SETTINGS',
  CATEGORY_DETAIL = 'CATEGORY_DETAIL',
  EXPENSE_DETAIL = 'EXPENSE_DETAIL'
}

import React, { useState, useEffect, useRef } from 'react';
