  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [sortBy, setSortBy] = useState<'date' | 'amount'>('date');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);

  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();

      if (selectedCategoryId !== 'all') {
        results = results.filter(e => e.categoryId === selectedCategoryId);
      }

      if (sortBy === 'date') {
        results.sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
      } else {
        results.sort((a, b) => a.amount - b.amount);
      }

      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId, sortBy]);

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;

    setIsGenerating(true);
    setShowPdfMenu(false);
    try {
      const element = reportRef.current;
      if (!element) return;

      // إظهار العنصر في مكان بعيد عن النظر لعمل اللقطة
      element.style.display = 'block';
      element.style.visibility = 'visible';
      element.style.position = 'fixed';
      element.style.left = '-10000px'; 
      element.style.top = '0';

      // انتظار بسيط لضمان رندر العناصر والرسوم
      await new Promise(resolve => setTimeout(resolve, 1000));

      const canvas = await html2canvas(element, {
        scale: 2,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        logging: false,
      });

      element.style.display = 'none';

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);

      if (action === 'download') {
        pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      } else {
        const blobUrl = pdf.output('bloburl');
        window.open(blobUrl, '_blank');
      }
    } catch (error) {
      console.error('PDF processing failed', error);
      alert('حدث خطأ أثناء معالجة التقرير.');
    } finally {
      setIsGenerating(false);
    }
  };

  const shareViaWhatsApp = () => {
    const category = categories.find(c => c.id === selectedCategoryId);
    if (!category || !category.phoneNumber) {
      alert('يجب اختيار قسم يحتوي على رقم هاتف مفعل لاستخدام هذه الميزة');
      return;
    }

    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const message = `*كشف مصروفات - تطبيق صرف*\n\nالقسم: ${category.name}\nالفترة: من ${fromDate} إلى ${toDate}\nإجمالي المصروفات: ${totalVal.toLocaleString()} ريال\nعدد العمليات: ${filteredExpenses.length}\n\n_تم الإرسال عبر تطبيق صرف_`;

    const whatsappUrl = `https://wa.me/967${category.phoneNumber}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || 
    exp.amount.toString().includes(searchQuery)
  );

  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      {/* Date Filters */}
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            من تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
          />
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            إلى تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
          />
        </div>
      </div>

      {/* Search Field */}
      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          placeholder="بحث في الملاحظات أو المبلغ..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
        {searchQuery && (
          <button 
            onClick={() => setSearchQuery('')}
            className="absolute left-3 top-3.5 text-slate-500 hover:text-white"
          >
            <X size={18} />
          </button>
        )}
      </div>

      {/* Categories Filter Pills */}
      <div className="flex gap-2 overflow-x-auto no-scrollbar py-1">
        <button 
          onClick={() => setSelectedCategoryId('all')}
          className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === 'all' ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
        >
          الكل
        </button>
        {categories.map(cat => (
          <button 
            key={cat.id}
            onClick={() => setSelectedCategoryId(cat.id)}
            className={`px-4 py-2 rounded-xl text-xs font-bold transition-all whitespace-nowrap ${selectedCategoryId === cat.id ? 'bg-blue-600 text-white shadow-lg shadow-blue-900/40' : 'bg-slate-900 text-slate-500 border border-slate-800'}`}
          >
            {cat.name}
          </button>
        ))}
      </div>

      {/* Summary Card */}
      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white flex justify-between items-center">
        <div>
          <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الكشف</p>
          <h3 className="text-2xl font-bold tabular-nums">{totalAmount.toLocaleString()} ريال</h3>
        </div>
        <div className="p-3 bg-white/20 rounded-2xl">
          <TrendingUp size={24} />
        </div>
      </div>

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-3">
        <button 
          disabled={filteredExpenses.length === 0 || isGenerating}
          onClick={() => setShowPdfMenu(true)}
          className={`px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 transition-all active:scale-95 ${isGenerating ? 'bg-slate-800 text-slate-500' : 'bg-slate-900 border border-slate-800 text-white hover:border-blue-500'}`}
        >
          {isGenerating ? <Loader2 size={24} className="animate-spin" /> : <FileDown size={24} className="text-blue-500" />}
          <span className="text-xs">كشف PDF</span>
        </button>

        <button 
          disabled={filteredExpenses.length === 0 || isGenerating || selectedCategoryId === 'all' || !categories.find(c => c.id === selectedCategoryId)?.phoneNumber}
          onClick={shareViaWhatsApp}
          className={`px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 transition-all active:scale-95 ${filteredExpenses.length === 0 || selectedCategoryId === 'all' || !categories.find(c => c.id === selectedCategoryId)?.phoneNumber ? 'bg-slate-800 text-slate-600 opacity-50 grayscale' : 'bg-green-600/10 border border-green-600/30 text-green-500 hover:bg-green-600 hover:text-white'}`}
        >
          <MessageCircle size={24} />
          <span className="text-xs">مشاركة واتساب</span>
        </button>
      </div>

      {/* Expense List */}
      <div className="space-y-3">
        <h4 className="font-bold text-slate-400 text-sm px-1">سجل العمليات</h4>
        {filteredExpenses.slice().reverse().map((exp) => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div 
              key={exp.id} 
              className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-colors"
              onClick={() => onExpenseSelect?.(exp)}
            >
              <div className="flex gap-4 items-center">
                <div className="w-12 h-12 flex-shrink-0 rounded-xl bg-slate-800 flex flex-col items-center justify-center text-[10px] text-blue-500 font-mono font-bold leading-tight">
                  <span className="opacity-50">SRF</span>
                  <span>{exp.serialNumber || '0'}</span>
                </div>
                <div>
                  <p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString()} ريال</p>
                  <p className="text-[10px] text-slate-500 mt-0.5">{exp.date} • {cat?.name || 'عام'}</p>
                </div>
              </div>
              <ChevronRight size={14} className="text-slate-700 rotate-180" />
            </div>
          );
        })}
      </div>

      {/* PDF Action Menu Modal */}
      {showPdfMenu && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] flex items-end justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-t-3xl rounded-b-xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold">خيارات كشف الحساب</h3>
              <button onClick={() => setShowPdfMenu(false)} className="p-2 text-slate-500 hover:text-white">
                <X size={20} />
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4 mb-4">
              <button 
                onClick={() => processPDF('view')}
                className="bg-slate-800 hover:bg-blue-600 text-white p-6 rounded-2xl flex flex-col items-center gap-3 transition-all active:scale-95 group border border-slate-700 hover:border-blue-500"
              >
                <div className="p-3 bg-slate-700 rounded-full group-hover:bg-white/20">
                  <ExternalLink size={24} />
                </div>
                <span className="font-bold">فتح / عرض</span>
              </button>

              <button 
                onClick={() => processPDF('download')}
                className="bg-slate-800 hover:bg-blue-600 text-white p-6 rounded-2xl flex flex-col items-center gap-3 transition-all active:scale-95 group border border-slate-700 hover:border-blue-500"
              >
                <div className="p-3 bg-slate-700 rounded-full group-hover:bg-white/20">
                  <Download size={24} />
                </div>
                <span className="font-bold">تحميل PDF</span>
              </button>
            </div>

            <button 
              onClick={() => setShowPdfMenu(false)}
              className="w-full py-4 text-slate-400 font-bold hover:text-white transition-colors"
            >
              إلغاء
            </button>
          </div>
        </div>
      )}

      {/* ========================================================== */}
      {/* PDF TEMPLATE */}
      {/* ========================================================== */}
      <div 
        ref={reportRef} 
        dir="rtl"
        style={{ 
          display: 'none', 
          width: '210mm', 
          minHeight: '297mm',
          padding: '20mm', 
          backgroundColor: '#ffffff', 
          color: '#000000',
          fontFamily: "'Tajawal', Arial, sans-serif"
        }}
      >
        {/* Header Section */}
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '3px solid #000000', paddingBottom: '15px', marginBottom: '25px' }}>
          <div>
            <h1 style={{ margin: 0, color: '#000000', fontSize: '30px', fontWeight: 'bold' }}>كشف مصروفات تفصيلي</h1>
            <p style={{ margin: '5px 0 0 0', color: '#333333', fontSize: '14px' }}>نظام "صرف" - إدارة مالية</p>
          </div>
          <div style={{ textAlign: 'left', color: '#000000' }}>
            <p style={{ margin: 0, fontSize: '12px', fontWeight: 'bold' }}>تاريخ الاستخراج: {new Date().toLocaleDateString('en-GB')}</p>
            <p style={{ margin: '3px 0 0 0', fontSize: '12px' }}>الفترة من {fromDate} إلى {toDate}</p>
          </div>
        </div>

        {/* Table Header */}
        <table style={{ width: '100%', borderCollapse: 'collapse', border: '2px solid #000000' }}>
          <thead>
            <tr style={{ backgroundColor: '#eeeeee' }}>
              <th style={{ padding: '12px 5px', border: '1px solid #000000', fontSize: '12px', color: '#000000', textAlign: 'center', width: '12%', fontWeight: 'bold' }}>رقم السند</th>
              <th style={{ padding: '12px 5px', border: '1px solid #000000', fontSize: '12px', color: '#000000', textAlign: 'right', width: '18%', fontWeight: 'bold' }}>القسم</th>
              <th style={{ padding: '12px 5px', border: '1px solid #000000', fontSize: '12px', color: '#000000', textAlign: 'center', width: '15%', fontWeight: 'bold' }}>المبلغ</th>
              <th style={{ padding: '12px 5px', border: '1px solid #000000', fontSize: '12px', color: '#000000', textAlign: 'center', width: '15%', fontWeight: 'bold' }}>التاريخ</th>
              <th style={{ padding: '12px 5px', border: '1px solid #000000', fontSize: '12px', color: '#000000', textAlign: 'right', width: '25%', fontWeight: 'bold' }}>الملاحظات</th>
              <th style={{ padding: '12px 5px', border: '1px solid #000000', fontSize: '12px', color: '#000000', textAlign: 'center', width: '15%', fontWeight: 'bold' }}>الصورة</th>
            </tr>
          </thead>
          <tbody>
            {filteredExpenses.map((exp) => {
              const cat = categories.find(c => c.id === exp.categoryId);
              return (
                <tr key={exp.id}>
                  <td style={{ padding: '10px 5px', border: '1px solid #000000', fontSize: '11px', textAlign: 'center', fontWeight: 'bold' }}>SRF-{exp.serialNumber || '0'}</td>
                  <td style={{ padding: '10px 5px', border: '1px solid #000000', fontSize: '11px', textAlign: 'right' }}>{cat?.name || 'عام'}</td>
                  <td style={{ padding: '10px 5px', border: '1px solid #000000', fontSize: '11px', textAlign: 'center', fontWeight: 'bold' }}>{exp.amount.toLocaleString()}</td>
                  <td style={{ padding: '10px 5px', border: '1px solid #000000', fontSize: '11px', textAlign: 'center' }}>{exp.date}</td>
                  <td style={{ padding: '10px 5px', border: '1px solid #000000', fontSize: '10px', textAlign: 'right' }}>{exp.notes || '-'}</td>
                  <td style={{ padding: '5px', border: '1px solid #000000', textAlign: 'center' }}>
                    {exp.image ? (
                      <img src={exp.image} style={{ width: '40px', height: '40px', objectFit: 'cover', borderRadius: '4px' }} alt="receipt" />
                    ) : (
                      <span style={{ fontSize: '9px', color: '#666666' }}>بدون</span>
                    )}
                  </td>
                </tr>
              );
            })}
          </tbody>
        </table>

        {/* Total Summary Section */}
        <div style={{ marginTop: '30px', display: 'flex', justifyContent: 'flex-start' }}>
          <div style={{ border: '2px solid #000000', padding: '20px', borderRadius: '5px', minWidth: '350px', backgroundColor: '#fafafa' }}>
            <div style={{ display: 'flex', justifyContent: 'space-between', marginBottom: '10px' }}>
              <span style={{ fontSize: '16px', fontWeight: 'bold', color: '#000000' }}>إجمالي مبلغ المصروفات:</span>
              <span style={{ fontSize: '22px', fontWeight: 'bold', color: '#000000' }}>{totalAmount.toLocaleString()} ريال</span>
            </div>
            <div style={{ display: 'flex', justifyContent: 'space-between', borderTop: '1px solid #000000', paddingTop: '10px' }}>
              <span style={{ fontSize: '14px', color: '#333333' }}>عدد العمليات الإجمالي:</span>
              <span style={{ fontSize: '14px', fontWeight: 'bold', color: '#000000' }}>{filteredExpenses.length} سند صرف</span>
            </div>
          </div>
        </div>

        {/* Footer */}
        <div style={{ marginTop: 'auto', paddingTop: '50px', textAlign: 'center', borderTop: '1px solid #dddddd' }}>
          <p style={{ fontSize: '10px', color: '#000000' }}>هذا الكشف تم توليده آلياً بواسطة تطبيق "صرف" - جميع الحقوق محفوظة {new Date().getFullYear()}</p>
        </div>
      </div>
    </div>
  );
};

export default ReportsView;

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { Category } from '../types';
import { 
  FolderPlus, 
  Trash2, 
  Phone,
  Search,
  X
} from 'lucide-react';

interface HomeViewProps {
  onAdd: () => void;
  onCategorySelect: (cat: Category) => void;
}

const HomeView: React.FC<HomeViewProps> = ({ onAdd, onCategorySelect }) => {
  const [categories, setCategories] = useState<Category[]>([]);
  const [categoryTotals, setCategoryTotals] = useState<Record<string, number>>({});
  const [isAddingCategory, setIsAddingCategory] = useState(false);
  const [newCategoryName, setNewCategoryName] = useState('');
  const [newCategoryPhone, setNewCategoryPhone] = useState('');
  const [totalExpenses, setTotalExpenses] = useState(0);
  const [searchQuery, setSearchQuery] = useState('');

  const loadData = async () => {
    const cats = await db.categories.toArray();
    cats.sort((a, b) => a.order - b.order);
    setCategories(cats);

    const expenses = await db.expenses.toArray();
    const totals: Record<string, number> = {};
    let grandTotal = 0;

    expenses.forEach(exp => {
      totals[exp.categoryId] = (totals[exp.categoryId] || 0) + exp.amount;
      grandTotal += exp.amount;
    });

    setCategoryTotals(totals);
    setTotalExpenses(grandTotal);
  };

  useEffect(() => {
    loadData();
  }, []);

  const handleAddCategory = async () => {
    if (!newCategoryName.trim()) return;
    const id = Date.now().toString();
    const order = categories.length;

    let phone = newCategoryPhone.trim().replace(/\D/g, '');
    if (phone.startsWith('0')) phone = phone.substring(1);

    await db.categories.add({
      id,
      name: newCategoryName,
      phoneNumber: phone || undefined,
      color: '#3b82f6',
      order
    });
    setNewCategoryName('');
    setNewCategoryPhone('');
    setIsAddingCategory(false);
    loadData();
  };

  const handleDeleteCategory = async (cat: Category) => {
    if (cat.isDefault) {
      alert('لا يمكن حذف القسم العام');
      return;
    }

    const count = await db.expenses.where('categoryId').equals(cat.id).count();
    if (count > 0) {
      const confirmMove = window.confirm(`هذا القسم يحتوي على ${count} مصروفات. هل تريد نقلها للقسم العام وحذف القسم؟`);
      if (confirmMove) {
        await db.expenses.where('categoryId').equals(cat.id).modify({ categoryId: 'default_general' });
        await db.categories.delete(cat.id);
        loadData();
      }
    } else {
      await db.categories.delete(cat.id);
      loadData();
    }
  };

  const filteredCategories = categories.filter(cat => 
    cat.name.toLowerCase().includes(searchQuery.toLowerCase())
  );

  return (
    <div className="space-y-6">
      <div className="bg-gradient-to-br from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white text-center">
        <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي المصاريف</p>
        <h2 className="text-4xl font-bold mb-2 tabular-nums">
          {totalExpenses.toLocaleString('ar-SA')} 
          <span className="text-lg mr-2 opacity-80">ريال يمني</span>
        </h2>
      </div>

      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          placeholder="بحث عن قسم..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
        {searchQuery && (
          <button 
            onClick={() => setSearchQuery('')}
            className="absolute left-3 top-3.5 text-slate-500 hover:text-white"
          >
            <X size={18} />
          </button>
        )}
      </div>

      <div className="flex justify-between items-center px-1">
        <h3 className="text-lg font-bold text-slate-300">الأقسام</h3>
        <button 
          onClick={() => setIsAddingCategory(true)}
          className="text-blue-500 hover:bg-blue-500/10 p-2 rounded-full transition-colors flex items-center gap-1"
        >
          <FolderPlus size={20} />
          <span className="text-sm font-medium">قسم جديد</span>
        </button>
      </div>

      <div className="grid grid-cols-2 gap-4">
        {filteredCategories.map((cat) => (
          <div 
            key={cat.id}
            className="bg-slate-900 border border-slate-800 rounded-2xl p-4 active:scale-95 transition-transform group relative cursor-pointer flex flex-col justify-between h-full"
            onClick={() => onCategorySelect(cat)}
          >
            <div>
              <div className="flex justify-between items-start mb-2">
                <div 
                  className="w-3 h-3 rounded-full mt-1" 
                  style={{ backgroundColor: cat.color }} 
                />
                {!cat.isDefault && (
                  <button 
                    onClick={(e) => {
                      e.stopPropagation();
                      handleDeleteCategory(cat);
                    }}
                    className="text-slate-600 hover:text-red-400 opacity-0 group-hover:opacity-100 transition-opacity"
                  >
                    <Trash2 size={16} />
                  </button>
                )}
              </div>
              <h4 className="font-bold text-slate-200 truncate">{cat.name}</h4>
              {cat.phoneNumber && (
                <div className="flex items-center gap-1 text-[10px] text-slate-500 mt-1">
                  <Phone size={10} />
                  <span dir="ltr">+967 {cat.phoneNumber}</span>
                </div>
              )}
            </div>
            <p className="text-blue-400 font-bold text-sm mt-3 tabular-nums text-right">
              {categoryTotals[cat.id] ? categoryTotals[cat.id].toLocaleString('ar-SA') : '٠'} <span className="text-[10px]">ر.ي</span>
            </p>
          </div>
        ))}
        {filteredCategories.length === 0 && searchQuery && (
          <div className="col-span-2 text-center py-10 text-slate-600">
            لا توجد أقسام تطابق بحثك
          </div>
        )}
      </div>

      {isAddingCategory && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-50 flex items-center justify-center p-6">
          <div className="bg-slate-900 border border-slate-800 w-full rounded-2xl p-6 shadow-2xl space-y-4">
            <h3 className="text-xl font-bold">إضافة قسم جديد</h3>

            <div className="space-y-3">
              <div>
