import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  ChevronRight, 
  Calendar, 
  Tag, 
  FileText, 
  Edit3,
  Trash2,
  Clock,
  ExternalLink,
  Loader2,
  Hash
} from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ExpenseDetailViewProps {
  expense: Expense;
  onBack: () => void;
  onEdit: (exp: Expense) => void;
}

const ExpenseDetailView: React.FC<ExpenseDetailViewProps> = ({ expense, onBack, onEdit }) => {
  const [category, setCategory] = useState<Category | null>(null);
  const [isGeneratingVoucher, setIsGeneratingVoucher] = useState(false);
  const voucherRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    db.categories.get(expense.categoryId).then(cat => setCategory(cat || null));
  }, [expense.categoryId]);

  const handleDelete = async () => {
    if (window.confirm('هل أنت متأكد من حذف هذا المصروف نهائياً؟')) {
      await db.expenses.delete(expense.id);
      onBack();
    }
  };

  const generateVoucherPDF = async () => {
    setIsGeneratingVoucher(true);
    try {
      const element = voucherRef.current;
      if (!element) return;

      // إظهار السند مؤقتاً لعمل اللقطة
      element.style.display = 'block';
      element.style.position = 'fixed';
      element.style.left = '-10000px';
      element.style.top = '0';

      await new Promise(resolve => setTimeout(resolve, 800));

      const canvas = await html2canvas(element, {
        scale: 2,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff'
      });

      element.style.display = 'none';

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a5' 
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);

      // بدلاً من pdf.save()، نقوم بفتح الملف في نافذة جديدة لعرضه
      const blobUrl = pdf.output('bloburl');
      window.open(blobUrl, '_blank');

    } catch (error) {
      console.error('Voucher generation failed', error);
      alert('حدث خطأ أثناء استخراج السند');
    } finally {
      setIsGeneratingVoucher(false);
    }
  };

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between mb-2">
        <button onClick={onBack} className="p-2 bg-slate-800 rounded-full hover:bg-slate-700 transition-colors">
          <ChevronRight size={20} />
        </button>
        <div className="text-center">
          <h2 className="text-xl font-bold">تفاصيل المصروف</h2>
          {expense.serialNumber && (
            <p className="text-[10px] text-blue-500 font-mono font-bold mt-1 tracking-widest">SRF-{expense.serialNumber}</p>
          )}
        </div>
        <button 
          onClick={handleDelete}
          className="p-2 bg-red-600/10 text-red-500 rounded-full hover:bg-red-600 hover:text-white transition-colors"
        >
          <Trash2 size={20} />
        </button>
      </div>

      {/* Amount Card */}
      <div className="bg-slate-900 rounded-3xl p-8 border border-slate-800 text-center shadow-xl">
        <p className="text-slate-500 text-sm mb-2">المبلغ المدفوع</p>
        <h3 className="text-4xl font-black text-blue-500 tabular-nums">
          {expense.amount.toLocaleString('ar-SA')} 
          <span className="text-lg text-slate-500 mr-2">ريال يمني</span>
        </h3>
      </div>

      <div className="h-px bg-slate-800/50 mx-4" />

      {/* Info Card */}
      <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden divide-y divide-slate-800">
        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-400">
            <Hash size={20} />
          </div>
          <div className="flex-grow">
            <p className="text-[10px] text-slate-500">رقم السند التسلسلي</p>
            <p className="font-bold text-slate-200 tabular-nums">SRF - {expense.serialNumber || 'غير متوفر'}</p>
          </div>
        </div>

        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-400">
            <Tag size={20} />
          </div>
          <div className="flex-grow">
            <p className="text-[10px] text-slate-500">القسم</p>
            <p className="font-bold text-slate-200">{category?.name || 'عام'}</p>
          </div>
          <div 
            className="w-3 h-3 rounded-full" 
            style={{ backgroundColor: category?.color || '#3b82f6' }} 
          />
        </div>

        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-400">
            <Calendar size={20} />
          </div>
          <div>
            <p className="text-[10px] text-slate-500">تاريخ الصرف</p>
            <p className="font-bold text-slate-200">{expense.date}</p>
          </div>
        </div>

        <div className="p-4 flex items-center gap-4">
          <div className="w-10 h-10 bg-slate-800 rounded-xl flex items-center justify-center text-slate-400">
            <Clock size={20} />
          </div>
          <div>
            <p className="text-[10px] text-slate-500">تاريخ التسجيل</p>
            <p className="font-bold text-slate-200 text-xs">
              {new Date(expense.createdAt).toLocaleDateString('ar-SA')} • {new Date(expense.createdAt).toLocaleTimeString('ar-SA', { hour: '2-digit', minute: '2-digit' })}
            </p>
          </div>
        </div>
      </div>

      {expense.notes && (
        <div className="bg-slate-900 rounded-3xl border border-slate-800 p-5">
          <div className="flex items-center gap-2 mb-3 text-slate-400">
            <FileText size={18} />
            <p className="text-xs font-bold uppercase tracking-widest">الملاحظات</p>
          </div>
          <p className="text-slate-300 text-sm leading-relaxed whitespace-pre-wrap">{expense.notes}</p>
        </div>
      )}

      {expense.image && (
        <div className="space-y-2">
          <p className="text-[10px] text-slate-500 px-4 uppercase font-bold tracking-widest">المستند / الفاتورة</p>
          <div className="bg-slate-900 rounded-3xl border border-slate-800 overflow-hidden shadow-lg group relative">
            <img 
              src={expense.image} 
              className="w-full h-auto max-h-[500px] object-contain bg-black/40" 
              alt="Expense document" 
            />
          </div>
        </div>
      )}

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-3 pt-2">
        <button 
          onClick={() => onEdit(expense)}
          className="bg-slate-800 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 active:scale-95 transition-all"
        >
          <Edit3 size={20} />
          <span>تعديل</span>
        </button>
        <button 
          disabled={isGeneratingVoucher}
          onClick={generateVoucherPDF}
          className="bg-blue-600 text-white font-bold py-4 rounded-2xl flex items-center justify-center gap-2 shadow-xl shadow-blue-900/20 active:scale-95 transition-all disabled:opacity-50"
        >
          {isGeneratingVoucher ? <Loader2 size={20} className="animate-spin" /> : <ExternalLink size={20} />}
          <span>عرض السند</span>
        </button>
      </div>

      {/* Hidden Voucher Template for PDF Export (Improved visibility with explicit black colors) */}
      <div 
        ref={voucherRef} 
        dir="rtl"
        style={{ 
          display: 'none',
          width: '148mm', 
          padding: '15mm', 
          backgroundColor: '#ffffff', 
          color: '#000000',
          fontFamily: "'Tajawal', Arial, sans-serif"
        }}
      >
        <div style={{ border: '4px double #000000', padding: '10mm', height: '100%', backgroundColor: '#ffffff' }}>
          <div style={{ display: 'flex', justifyContent: 'space-between', borderBottom: '2px solid #000000', paddingBottom: '5mm', marginBottom: '8mm' }}>
            <div>
              <h1 style={{ margin: 0, fontSize: '24px', fontWeight: 'bold', color: '#000000' }}>سند صــرف</h1>
