import React, { useState, useEffect } from 'react';
import { db, initializeDb } from './db';
import { ViewState, Category, Expense, AppSettings } from './types';
import { 
  Plus, 
  Home, 
  PieChart, 
  Settings as SettingsIcon
} from 'lucide-react';

// View Components
import HomeView from './components/HomeView';
import AddExpenseView from './components/AddExpenseView';
import ReportsView from './components/ReportsView';
import SettingsView from './components/SettingsView';
import CategoryDetailView from './components/CategoryDetailView';
import ExpenseDetailView from './components/ExpenseDetailView';

const App: React.FC = () => {
  const [currentView, setCurrentView] = useState<ViewState>(ViewState.HOME);
  const [selectedCategory, setSelectedCategory] = useState<Category | null>(null);
  const [selectedExpense, setSelectedExpense] = useState<Expense | null>(null);
  const [editingExpense, setEditingExpense] = useState<Expense | null>(null);
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [initialized, setInitialized] = useState(false);

  useEffect(() => {
    const init = async () => {
      await initializeDb();
      const s = await db.settings.get('app_settings');
      if (s) {
        setSettings(s);
      }
      setInitialized(true);
    };
    init();
  }, []);

  if (!initialized || !settings) return <div className="min-h-screen bg-slate-950 flex items-center justify-center text-white font-bold">جاري التحميل...</div>;

  const renderView = () => {
    switch (currentView) {
      case ViewState.HOME:
        return <HomeView 
          onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} 
          onCategorySelect={(cat) => {
            setSelectedCategory(cat);
            setCurrentView(ViewState.CATEGORY_DETAIL);
          }}
        />;
      case ViewState.ADD_EXPENSE:
        return <AddExpenseView 
          onClose={() => {
            setEditingExpense(null);
            setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.HOME);
          }} 
          initialData={editingExpense}
          preselectedCategoryId={selectedCategory?.id}
        />;
      case ViewState.REPORTS:
        return <ReportsView onExpenseSelect={(exp) => {
          setSelectedExpense(exp);
          setCurrentView(ViewState.EXPENSE_DETAIL);
        }} />;
      case ViewState.SETTINGS:
        return <SettingsView onUpdateSettings={setSettings} />;
      case ViewState.CATEGORY_DETAIL:
        return selectedCategory ? (
          <CategoryDetailView 
            category={selectedCategory} 
            onBack={() => {
              setSelectedCategory(null);
              setCurrentView(ViewState.HOME);
            }}
            onExpenseSelect={(exp) => {
              setSelectedExpense(exp);
              setCurrentView(ViewState.EXPENSE_DETAIL);
            }}
            onAddExpense={() => {
              setEditingExpense(null);
              setCurrentView(ViewState.ADD_EXPENSE);
            }}
          />
        ) : null;
      case ViewState.EXPENSE_DETAIL:
        return selectedExpense ? (
          <ExpenseDetailView 
            expense={selectedExpense}
            onBack={() => setCurrentView(selectedCategory ? ViewState.CATEGORY_DETAIL : ViewState.REPORTS)}
            onEdit={(exp) => {
              setEditingExpense(exp);
              setCurrentView(ViewState.ADD_EXPENSE);
            }}
          />
        ) : null;
      default:
        return <HomeView onAdd={() => setCurrentView(ViewState.ADD_EXPENSE)} onCategorySelect={(cat) => {
          setSelectedCategory(cat);
          setCurrentView(ViewState.CATEGORY_DETAIL);
        }} />;
    }
  };

  return (
    <div className="min-h-screen pb-20 max-w-md mx-auto bg-slate-950 text-slate-100 flex flex-col relative shadow-2xl">
      <header className="p-4 flex justify-between items-center border-b border-slate-800 sticky top-0 bg-slate-950/80 backdrop-blur-md z-40">
        <div className="flex items-center gap-2">
          <div className="w-8 h-8 bg-blue-600 rounded-lg flex items-center justify-center font-bold text-white shadow-lg shadow-blue-900/40">ص</div>
          <h1 className="text-2xl font-bold bg-gradient-to-l from-blue-400 to-blue-600 bg-clip-text text-transparent">صرف</h1>
        </div>
      </header>

      <main className="flex-grow p-4 overflow-y-auto">
        {renderView()}
      </main>

      <nav className="fixed bottom-0 left-0 right-0 max-w-md mx-auto bg-slate-900 border-t border-slate-800 flex justify-around p-3 z-50 rounded-t-3xl shadow-2xl">
        <button 
          onClick={() => {
            setSelectedCategory(null);
            setCurrentView(ViewState.HOME);
          }}
          className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.HOME || currentView === ViewState.CATEGORY_DETAIL ? 'text-blue-500' : 'text-slate-500'}`}
        >
          <Home size={22} />
          <span className="text-[10px] font-bold">الرئيسية</span>
        </button>

        <button 
          onClick={() => {
            setEditingExpense(null);
            setCurrentView(ViewState.ADD_EXPENSE);
          }}
          className="bg-blue-600 p-4 rounded-full -mt-10 shadow-xl shadow-blue-900/60 text-white active:scale-90 transition-transform ring-4 ring-slate-950"
        >
          <Plus size={28} />
        </button>

        <button 
          onClick={() => setCurrentView(ViewState.REPORTS)}
          className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.REPORTS ? 'text-blue-500' : 'text-slate-500'}`}
        >
          <PieChart size={22} />
          <span className="text-[10px] font-bold">التقارير</span>
        </button>

        <button 
          onClick={() => setCurrentView(ViewState.SETTINGS)}
          className={`flex flex-col items-center gap-1 transition-colors ${currentView === ViewState.SETTINGS ? 'text-blue-500' : 'text-slate-500'}`}
        >
          <SettingsIcon size={22} />
          <span className="text-[10px] font-bold">الإعدادات</span>
        </button>
      </nav>
    </div>
  );
};

export default App;

export interface Category {
  id: string;
  name: string;
  color: string;
  order: number;
  phoneNumber?: string; // حقل اختياري لرقم الهاتف
  isDefault?: boolean;
}

export interface Expense {
  id: string;
  categoryId: string;
  amount: number;
  date: string;
  notes?: string;
  image?: string; // base64
  createdAt: number;
  serialNumber?: number; // رقم تسلسلي (SRF-1)
}

export interface RecurringReminder {
  id: string;
  title: string;
  amount: number;
  categoryId: string;
  dayOfMonth: number;
}

export interface AppSettings {
  showImages: boolean;
  showNotes: boolean;
}

export enum ViewState {
  HOME = 'HOME',
  ADD_EXPENSE = 'ADD_EXPENSE',
  EDIT_EXPENSE = 'EDIT_EXPENSE',
  REPORTS = 'REPORTS',
  SETTINGS = 'SETTINGS',
  CATEGORY_DETAIL = 'CATEGORY_DETAIL',
  EXPENSE_DETAIL = 'EXPENSE_DETAIL'
}

import Dexie, { type Table } from 'dexie';
import { Category, Expense, AppSettings, RecurringReminder } from './types';

// Define the database class extending Dexie
export class SarfDB extends Dexie {
  categories!: Table<Category>;
  expenses!: Table<Expense>;
  settings!: Table<AppSettings>;
  reminders!: Table<RecurringReminder>;

  constructor() {
    super('SarfDB');
    // Version 3 includes the reminders table
    (this as Dexie).version(3).stores({
      categories: 'id, name, order',
      expenses: 'id, categoryId, date, createdAt',
      settings: '',
      reminders: 'id, categoryId, dayOfMonth'
    });
  }
}

export const db = new SarfDB();

export async function initializeDb() {
  const count = await db.categories.count();
  if (count === 0) {
    await db.categories.add({
      id: 'default_general',
      name: 'عام',
      color: '#3b82f6',
      order: 0,
      isDefault: true
    });
  }

  const settingsCount = await db.settings.count();
  if (settingsCount === 0) {
    await db.settings.put({
      showImages: true,
      showNotes: true
    }, 'app_settings');
  }
}

import React, { useState, useEffect } from 'react';
import { db } from '../db';
import { AppSettings, RecurringReminder, Category } from '../types';
import { 
  Eye, 
  Download, 
  Upload, 
  Palette,
  Trash2,
  Bell,
  Plus,
  X,
  Calendar,
  Tag
} from 'lucide-react';

interface SettingsViewProps {
  onUpdateSettings: (s: AppSettings) => void;
}

const SettingsView: React.FC<SettingsViewProps> = ({ onUpdateSettings }) => {
  const [settings, setSettings] = useState<AppSettings | null>(null);
  const [reminders, setReminders] = useState<RecurringReminder[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [isAddingReminder, setIsAddingReminder] = useState(false);

  // New reminder form state
  const [newReminderTitle, setNewReminderTitle] = useState('');
  const [newReminderAmount, setNewReminderAmount] = useState('');
  const [newReminderCategory, setNewReminderCategory] = useState('default_general');
  const [newReminderDay, setNewReminderDay] = useState('1');

  useEffect(() => {
    db.settings.get('app_settings').then(s => {
      if (s) setSettings(s);
    });
    loadReminders();
    db.categories.toArray().then(setCategories);
  }, []);

  const loadReminders = async () => {
    const r = await db.reminders.toArray();
    setReminders(r);
  };

  const updateSetting = async (key: keyof AppSettings, value: any) => {
    if (!settings) return;
    const newSettings = { ...settings, [key]: value };
    await db.settings.put(newSettings, 'app_settings');
    setSettings(newSettings);
    onUpdateSettings(newSettings);
  };

  const handleAddReminder = async () => {
    if (!newReminderTitle.trim() || !newReminderAmount) return;

    const reminder: RecurringReminder = {
      id: Date.now().toString(),
      title: newReminderTitle,
      amount: parseFloat(newReminderAmount),
      categoryId: newReminderCategory,
      dayOfMonth: parseInt(newReminderDay)
    };

    await db.reminders.add(reminder);
    setNewReminderTitle('');
    setNewReminderAmount('');
    setIsAddingReminder(false);
    loadReminders();
  };

  const deleteReminder = async (id: string) => {
    await db.reminders.delete(id);
    loadReminders();
  };

  const exportData = async () => {
    const cats = await db.categories.toArray();
    const exps = await db.expenses.toArray();
    const sets = await db.settings.get('app_settings');
    const rems = await db.reminders.toArray();

    const data = JSON.stringify({ cats, exps, sets, rems });
    const blob = new Blob([data], { type: 'application/json' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = `sarf_backup_${new Date().toISOString().split('T')[0]}.json`;
    a.click();
    URL.revokeObjectURL(url);
  };

  const importData = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (event) => {
      try {
        const data = JSON.parse(event.target?.result as string);
        if (window.confirm('سيتم مسح البيانات الحالية واستبدالها بالنسخة الاحتياطية. هل أنت متأكد؟')) {
          await db.categories.clear();
          await db.expenses.clear();
          await db.reminders.clear();
          await db.categories.bulkAdd(data.cats);
          await db.expenses.bulkAdd(data.exps);
          if (data.rems) await db.reminders.bulkAdd(data.rems);
          alert('تم استيراد البيانات بنجاح!');
          window.location.reload();
        }
      } catch (err) {
        alert('خطأ في ملف النسخة الاحتياطية');
      }
    };
    reader.readAsText(file);
  };

  if (!settings) return null;

  return (
    <div className="space-y-6">
      <h2 className="text-xl font-bold mb-4">الإعدادات</h2>

      {/* المصروفات المتكررة */}
      <section className="space-y-3">
        <div className="flex justify-between items-center px-2">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider">المصروفات المتكررة</h3>
          <button 
            onClick={() => setIsAddingReminder(true)}
            className="text-blue-500 flex items-center gap-1 text-xs font-bold"
          >
            <Plus size={14} />
            إضافة مصروف دوري
          </button>
        </div>

        <div className="bg-slate-900 rounded-2xl border border-slate-800 divide-y divide-slate-800">
          {reminders.length === 0 ? (
            <div className="p-8 text-center text-slate-600">
              <Bell size={24} className="mx-auto mb-2 opacity-20" />
              <p className="text-xs">لا يوجد مصروفات متكررة حالياً</p>
            </div>
          ) : (
            reminders.map(rem => {
              const cat = categories.find(c => c.id === rem.categoryId);
              return (
                <div key={rem.id} className="p-4 flex justify-between items-center">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-xl bg-blue-500/10 flex items-center justify-center text-blue-500">
                      <Bell size={18} />
                    </div>
                    <div>
                      <p className="font-bold text-sm">{rem.title}</p>
                      <p className="text-[10px] text-slate-500">
                        {rem.amount.toLocaleString()} ر.ي • كل يوم {rem.dayOfMonth} في الشهر
                      </p>
                    </div>
                  </div>
                  <button onClick={() => deleteReminder(rem.id)} className="p-2 text-slate-700 hover:text-red-500 transition-colors">
                    <Trash2 size={16} />
                  </button>
                </div>
              );
            })
          )}
        </div>
      </section>

      <section className="space-y-2">
        <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider px-2">العرض</h3>
        <div className="bg-slate-900 rounded-2xl border border-slate-800 divide-y divide-slate-800">
          <div className="p-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <Eye size={20} className="text-slate-400" />
              <span>إظهار الملاحظات</span>
            </div>
            <button 
              onClick={() => updateSetting('showNotes', !settings.showNotes)}
              className={`w-12 h-6 rounded-full transition-colors relative ${settings.showNotes ? 'bg-blue-600' : 'bg-slate-700'}`}
            >
              <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${settings.showNotes ? 'left-1' : 'left-7'}`} />
            </button>
          </div>
          <div className="p-4 flex justify-between items-center">
            <div className="flex items-center gap-3">
              <Palette size={20} className="text-slate-400" />
              <span>إظهار الصور في القوائم</span>
            </div>
            <button 
              onClick={() => updateSetting('showImages', !settings.showImages)}
              className={`w-12 h-6 rounded-full transition-colors relative ${settings.showImages ? 'bg-blue-600' : 'bg-slate-700'}`}
            >
              <div className={`absolute top-1 w-4 h-4 rounded-full bg-white transition-all ${settings.showImages ? 'left-1' : 'left-7'}`} />
            </button>
          </div>
        </div>
      </section>

      <section className="space-y-2">
        <h3 className="text-xs font-bold text-slate-500 uppercase tracking-wider px-2">البيانات</h3>
        <div className="bg-slate-900 rounded-2xl border border-slate-800 divide-y divide-slate-800">
          <button 
            onClick={exportData}
            className="w-full p-4 flex items-center gap-3 hover:bg-slate-800/50 transition-colors text-right"
          >
            <Download size={20} className="text-blue-400" />
            <div className="text-right">
              <p>تصدير نسخة احتياطية</p>
              <p className="text-[10px] text-slate-500">حفظ جميع البيانات والصور في ملف خارجي</p>
            </div>
          </button>
          <label className="w-full p-4 flex items-center gap-3 hover:bg-slate-800/50 transition-colors cursor-pointer">
            <Upload size={20} className="text-green-400" />
            <div className="text-right flex-grow">
              <p>استيراد نسخة احتياطية</p>
