export default ExpenseDetailView;

import React, { useState, useEffect, useRef } from 'react';
import { db } from '../db';
import { Expense, Category } from '../types';
import { 
  FileDown, 
  TrendingUp,
  BarChart3,
  Loader2,
  Calendar,
  MessageCircle,
  ChevronRight,
  Search,
  X,
  ExternalLink,
  Download,
  FileText,
  Sparkles,
  Layers
} from 'lucide-react';
import html2canvas from 'html2canvas';
import { jsPDF } from 'jspdf';

interface ReportsViewProps {
  onExpenseSelect?: (exp: Expense) => void;
}

const ReportsView: React.FC<ReportsViewProps> = ({ onExpenseSelect }) => {
  const [expenses, setExpenses] = useState<Expense[]>([]);
  const [categories, setCategories] = useState<Category[]>([]);
  const [fromDate, setFromDate] = useState(new Date(new Date().setDate(1)).toISOString().split('T')[0]);
  const [toDate, setToDate] = useState(new Date().toISOString().split('T')[0]);
  const [selectedCategoryId, setSelectedCategoryId] = useState('all');
  const [sortBy, setSortBy] = useState<'date' | 'amount'>('date');
  const [searchQuery, setSearchQuery] = useState('');
  const [isGenerating, setIsGenerating] = useState(false);
  const [showPdfMenu, setShowPdfMenu] = useState(false);

  // Progress state
  const [progress, setProgress] = useState(0);
  const [statusMessage, setStatusMessage] = useState('');

  const reportRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const load = async () => {
      const cats = await db.categories.toArray();
      setCategories(cats);

      let results = await db.expenses.where('date').between(fromDate, toDate, true, true).toArray();

      if (selectedCategoryId !== 'all') {
        results = results.filter(e => e.categoryId === selectedCategoryId);
      }

      if (sortBy === 'date') {
        results.sort((a, b) => new Date(b.date).getTime() - new Date(a.date).getTime());
      } else {
        results.sort((a, b) => b.amount - a.amount);
      }

      setExpenses(results);
    };
    load();
  }, [fromDate, toDate, selectedCategoryId, sortBy]);

  const processPDF = async (action: 'download' | 'view') => {
    if (expenses.length === 0 || isGenerating) return;

    setIsGenerating(true);
    setShowPdfMenu(false);
    setProgress(10);
    setStatusMessage('جاري تحضير البيانات وفلترة العمليات...');

    try {
      const element = reportRef.current;
      if (!element) return;

      await new Promise(r => setTimeout(r, 500));
      setProgress(30);
      setStatusMessage('جاري بناء هيكل التقرير الرقمي...');

      element.style.display = 'block';
      element.style.visibility = 'visible';
      element.style.position = 'fixed';
      element.style.left = '-10000px'; 
      element.style.top = '0';

      await new Promise(resolve => setTimeout(resolve, 800));
      setProgress(60);
      setStatusMessage('جاري التقاط لقطات عالية الجودة (Snapshot)...');

      const canvas = await html2canvas(element, {
        scale: 2,
        useCORS: true,
        allowTaint: true,
        backgroundColor: '#ffffff',
        logging: false,
      });

      element.style.display = 'none';
      setProgress(85);
      setStatusMessage('جاري تحويل اللقطات إلى ملف PDF معتمد...');

      const imgData = canvas.toDataURL('image/png');
      const pdf = new jsPDF({
        orientation: 'portrait',
        unit: 'mm',
        format: 'a4'
      });

      const pdfWidth = pdf.internal.pageSize.getWidth();
      const pdfHeight = (canvas.height * pdfWidth) / canvas.width;

      pdf.addImage(imgData, 'PNG', 0, 0, pdfWidth, pdfHeight);

      setProgress(100);
      setStatusMessage('اكتملت العملية بنجاح!');
      await new Promise(r => setTimeout(r, 500));

      if (action === 'download') {
        pdf.save(`تقرير_صرف_${fromDate}.pdf`);
      } else {
        const blobUrl = pdf.output('bloburl');
        window.open(blobUrl, '_blank');
      }
    } catch (error) {
      console.error('PDF processing failed', error);
      alert('حدث خطأ أثناء معالجة التقرير.');
    } finally {
      setIsGenerating(false);
      setProgress(0);
      setStatusMessage('');
    }
  };

  const shareViaWhatsApp = () => {
    const category = categories.find(c => c.id === selectedCategoryId);
    const categoryName = selectedCategoryId === 'all' ? 'كافة الأقسام' : (category?.name || 'غير معروف');

    if (selectedCategoryId !== 'all' && (!category || !category.phoneNumber)) {
      alert('يجب اختيار قسم يحتوي على رقم هاتف مفعل لاستخدام هذه الميزة، أو اختر "كافة الأقسام" للمشاركة العامة');
      return;
    }

    const totalVal = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);
    const message = `*كشف مصروفات - تطبيق صرف*\n\nالقسم: ${categoryName}\nالفترة: من ${fromDate} إلى ${toDate}\nإجمالي المصروفات: ${totalVal.toLocaleString()} ريال يمني\nعدد العمليات: ${filteredExpenses.length}\n\n_تم الإرسال عبر تطبيق صرف_`;

    const phone = selectedCategoryId !== 'all' ? `967${category?.phoneNumber}` : '';
    const whatsappUrl = `https://wa.me/${phone}?text=${encodeURIComponent(message)}`;
    window.open(whatsappUrl, '_blank');
  };

  const filteredExpenses = expenses.filter(exp => 
    exp.notes?.toLowerCase().includes(searchQuery.toLowerCase()) || 
    exp.amount.toString().includes(searchQuery)
  );

  const totalAmount = filteredExpenses.reduce((acc, curr) => acc + curr.amount, 0);

  return (
    <div className="space-y-6 pb-10">
      <h2 className="text-xl font-bold mb-4">التقارير والكشوفات</h2>

      {/* Date Filters */}
      <div className="grid grid-cols-2 gap-3">
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            من تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={fromDate}
            onChange={(e) => setFromDate(e.target.value)}
          />
        </div>
        <div className="bg-slate-900 border border-slate-800 p-4 rounded-2xl">
          <label className="block text-xs text-slate-500 mb-1 flex items-center gap-1">
            <Calendar size={12} />
            إلى تاريخ
          </label>
          <input 
            type="date"
            className="w-full bg-transparent text-sm outline-none text-blue-400"
            value={toDate}
            onChange={(e) => setToDate(e.target.value)}
          />
        </div>
      </div>

      {/* Category Filter (The Missing Part) */}
      <div className="space-y-2">
        <label className="text-xs text-slate-500 px-1 flex items-center gap-1">
          <Layers size={12} />
          تصفية حسب القسم
        </label>
        <div className="flex gap-2 overflow-x-auto pb-2 no-scrollbar">
          <button
            onClick={() => setSelectedCategoryId('all')}
            className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm transition-all font-bold ${
              selectedCategoryId === 'all' 
                ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-900/40' 
                : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700'
            }`}
          >
            الكل
          </button>
          {categories.map(cat => (
            <button
              key={cat.id}
              onClick={() => setSelectedCategoryId(cat.id)}
              className={`flex-shrink-0 px-5 py-2 rounded-full border text-sm transition-all font-bold ${
                selectedCategoryId === cat.id 
                  ? 'bg-blue-600 border-blue-600 text-white shadow-lg shadow-blue-900/40' 
                  : 'bg-slate-900 border-slate-800 text-slate-400 hover:border-slate-700'
              }`}
            >
              {cat.name}
            </button>
          ))}
        </div>
      </div>

      {/* Search Field */}
      <div className="relative">
        <Search className="absolute right-3 top-3.5 text-slate-500" size={18} />
        <input 
          className="w-full bg-slate-900 border border-slate-800 rounded-2xl pr-10 pl-10 py-3 text-sm focus:ring-2 focus:ring-blue-500 outline-none transition-all"
          placeholder="بحث في الملاحظات أو المبلغ..."
          value={searchQuery}
          onChange={(e) => setSearchQuery(e.target.value)}
        />
        {searchQuery && (
          <button 
            onClick={() => setSearchQuery('')}
            className="absolute left-3 top-3.5 text-slate-500 hover:text-white"
          >
            <X size={18} />
          </button>
        )}
      </div>

      {/* Summary Card */}
      <div className="bg-gradient-to-r from-blue-600 to-indigo-700 p-6 rounded-3xl shadow-xl shadow-blue-900/20 text-white flex justify-between items-center">
        <div>
          <p className="text-blue-100 text-sm mb-1 font-medium">إجمالي الكشف</p>
          <h3 className="text-2xl font-bold tabular-nums">{totalAmount.toLocaleString()} ريال يمني</h3>
        </div>
        <div className="p-3 bg-white/20 rounded-2xl">
          <TrendingUp size={24} />
        </div>
      </div>

      {/* Action Buttons */}
      <div className="grid grid-cols-2 gap-3">
        <button 
          disabled={filteredExpenses.length === 0 || isGenerating}
          onClick={() => setShowPdfMenu(true)}
          className={`px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 transition-all active:scale-95 ${isGenerating ? 'bg-slate-800 text-slate-500' : 'bg-slate-900 border border-slate-800 text-white hover:border-blue-500'}`}
        >
          {isGenerating ? <Loader2 size={24} className="animate-spin" /> : <FileDown size={24} className="text-blue-500" />}
          <span className="text-xs">كشف PDF</span>
        </button>

        <button 
          disabled={filteredExpenses.length === 0 || isGenerating}
          onClick={shareViaWhatsApp}
          className={`px-4 py-4 rounded-2xl font-bold flex flex-col items-center justify-center gap-2 transition-all active:scale-95 ${filteredExpenses.length === 0 ? 'bg-slate-800 text-slate-600 opacity-50 grayscale' : 'bg-green-600/10 border border-green-600/30 text-green-500 hover:bg-green-600 hover:text-white'}`}
        >
          <MessageCircle size={24} />
          <span className="text-xs">مشاركة واتساب</span>
        </button>
      </div>

      {/* Expense List */}
      <div className="space-y-3">
        <h4 className="font-bold text-slate-400 text-sm px-1">سجل العمليات للفترة المحددة</h4>
        {filteredExpenses.map((exp) => {
          const cat = categories.find(c => c.id === exp.categoryId);
          return (
            <div 
              key={exp.id} 
              className="bg-slate-900/50 p-4 rounded-2xl flex justify-between items-center border border-slate-800/30 cursor-pointer active:bg-slate-800 transition-colors"
              onClick={() => onExpenseSelect?.(exp)}
            >
              <div className="flex gap-4 items-center">
                <div className="w-12 h-12 flex-shrink-0 rounded-xl bg-slate-800 flex flex-col items-center justify-center text-[10px] text-blue-500 font-mono font-bold leading-tight">
                  <span className="opacity-50">SRF</span>
                  <span>{exp.serialNumber || '0'}</span>
                </div>
                <div>
                  <p className="font-bold tabular-nums text-slate-200">{exp.amount.toLocaleString()} ر.ي</p>
                  <p className="text-[10px] text-slate-500 mt-0.5">{exp.date} • {cat?.name || 'عام'}</p>
                </div>
              </div>
              <ChevronRight size={14} className="text-slate-700 rotate-180" />
            </div>
          );
        })}
        {filteredExpenses.length === 0 && (
          <div className="text-center py-10 bg-slate-900/20 rounded-3xl border border-dashed border-slate-800">
             <p className="text-slate-600 text-sm">لا توجد بيانات تطابق الفلترة الحالية</p>
          </div>
        )}
      </div>

      {/* Progress Overlay */}
      {isGenerating && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md z-[200] flex flex-col items-center justify-center p-8 animate-in fade-in duration-300">
          <div className="w-full max-w-xs space-y-8 text-center">
            <div className="relative flex items-center justify-center">
              <div className="w-24 h-24 rounded-full border-4 border-slate-800 border-t-blue-500 animate-spin" />
              <FileText className="absolute text-blue-500" size={32} />
            </div>

            <div className="space-y-4">
              <div className="flex justify-between items-end mb-1 px-1">
                <span className="text-blue-400 text-xs font-bold flex items-center gap-1">
                   <Sparkles size={12} />
                   {statusMessage}
                </span>
                <span className="text-slate-500 text-[10px] font-mono">{progress}%</span>
              </div>
              <div className="w-full h-2 bg-slate-800 rounded-full overflow-hidden shadow-inner">
                <div 
                  className="h-full bg-gradient-to-r from-blue-600 to-blue-400 transition-all duration-500 ease-out shadow-[0_0_10px_rgba(59,130,246,0.5)]"
                  style={{ width: `${progress}%` }}
                />
              </div>
            </div>

            <p className="text-slate-500 text-[10px] font-medium animate-pulse">
              برجاء عدم إغلاق التطبيق حتى اكتمال التصدير...
            </p>
          </div>
        </div>
      )}

      {/* PDF Action Menu Modal */}
      {showPdfMenu && (
        <div className="fixed inset-0 bg-black/60 backdrop-blur-sm z-[60] flex items-end justify-center p-4">
          <div className="bg-slate-900 border border-slate-800 w-full max-w-md rounded-t-3xl rounded-b-xl p-6 shadow-2xl animate-in slide-in-from-bottom duration-300">
            <div className="flex justify-between items-center mb-6">
              <h3 className="text-lg font-bold">خيارات كشف الحساب</h3>
              <button onClick={() => setShowPdfMenu(false)} className="p-2 text-slate-500 hover:text-white">
                <X size={20} />
              </button>
            </div>

            <div className="grid grid-cols-2 gap-4 mb-4">
              <button 
                onClick={() => processPDF('view')}
                className="bg-slate-800 hover:bg-blue-600 text-white p-6 rounded-2xl flex flex-col items-center gap-3 transition-all active:scale-95 group border border-slate-700 hover:border-blue-500"
              >
                <div className="p-3 bg-slate-700 rounded-full group-hover:bg-white/20">
                  <ExternalLink size={24} />
                </div>
                <span className="font-bold">فتح / عرض</span>
              </button>

              <button 
                onClick={() => processPDF('download')}
                className="bg-slate-800 hover:bg-blue-600 text-white p-6 rounded-2xl flex flex-col items-center gap-3 transition-all active:scale-95 group border border-slate-700 hover:border-blue-500"
              >
                <div className="p-3 bg-slate-700 rounded-full group-hover:bg-white/20">
                  <Download size={24} />
                </div>
                <span className="font-bold">تحميل PDF</span>
              </button>
            </div>
          </div>
        </div>
      )}

      {/* PDF TEMPLATE (Hidden) */}
      <div 
        ref={reportRef} 
        dir="rtl"
        style={{ 
          display: 'none', 
          width: '210mm', 
          padding: '20mm', 
          backgroundColor: '#ffffff', 
          color: '#000000',
          fontFamily: "'Tajawal', Arial, sans-serif"
        }}
      >
        <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', borderBottom: '3px solid #000000', paddingBottom: '15px', marginBottom: '25px' }}>
          <div>
            <h1 style={{ margin: 0, color: '#000000', fontSize: '30px', fontWeight: 'bold' }}>كشف مصروفات تفصيلي</h1>
            <p style={{ margin: '5px 0 0 0', color: '#333333', fontSize: '14px' }}>نظام "صرف" - إدارة مالية</p>
            <p style={{ margin: '3px 0 0 0', color: '#666666', fontSize: '12px' }}>القسم المختار: {selectedCategoryId === 'all' ? 'كافة الأقسام' : categories.find(c => c.id === selectedCategoryId)?.name}</p>
          </div>
          <div style={{ textAlign: 'left', color: '#000000' }}>
            <p style={{ margin: 0, fontSize: '12px', fontWeight: 'bold' }}>تاريخ الاستخراج: {new Date().toLocaleDateString('en-GB')}</p>
